import{d as S,C as g,o as V,c as N,a3 as l,E as a,j as i,a as e}from"./chunks/framework.Q4yG9rk_.js";const B=JSON.parse('{"title":"庄子·骈拇","description":"以物易其性——拇枝指、凫胫鹤胫到自见自得，理解庄子对外篇批判仁义的第一个命题。","frontmatter":{"title":"庄子·骈拇","description":"以物易其性——拇枝指、凫胫鹤胫到自见自得，理解庄子对外篇批判仁义的第一个命题。","category":"guide","aliases":["骈拇","庄子骈拇","zhuangzi chapter 08"],"source":["《庄子·骈拇》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-08.md","filePath":"daoism/zhuang-zi/chapter-08.md","lastUpdated":1792641266000}'),A={name:"daoism/zhuang-zi/chapter-08.md"},K=S({...A,setup(R){const d=[{id:"pian_s1",label:"骈拇枝指出乎性哉……而侈于德",sentences:[[{text:"骈拇",glossary:"pian_mu"},{text:"枝指",glossary:"zhi_zhi"},{text:"出乎性哉",glossary:"chu_hu_xing"},"，而",{text:"侈",glossary:"chi_yu"},"于德；"]]},{id:"pian_s2",label:"附赘县疣出乎形哉……而侈于性",sentences:[[{text:"附",glossary:"fu_zhui"},{text:"赘县",glossary:"zhui_xian"},{text:"疣",glossary:"you_liu"},{text:"出乎形哉",glossary:"chu_hu_xing"},"，而",{text:"侈",glossary:"chi_yu"},"于性；"]]},{id:"pian_s3",label:"多方乎仁义而用之者……而非道德之正也",sentences:[["多方乎仁义而用之者，",{text:"列",glossary:"lie_pai"},"于",{text:"五藏",glossary:"wu_zang"},"哉，而",{text:"非道德之正也",glossary:"fei_zhengdao"},"。"]]},{id:"pian_s4",label:"是故骈于足者……多方于聪明之用也",sentences:[["是故",{text:"骈于足者",glossary:"pian_zu"},"，连无用之肉也；"],["枝于手者，树无用之指也；"],["多方",{text:"骈枝",glossary:"pian_zhi_wu"},"于",{text:"五藏之情者",glossary:"wu_zang_qing"},"，"],[{text:"淫",glossary:"yin_guo"},{text:"僻",glossary:"pi_pian"},"于",{text:"仁义之行",glossary:"renyi_xing"},"，而",{text:"多",glossary:"duo_fan"},{text:"方",glossary:"fang_fan"},"于",{text:"聪明之用也",glossary:"cong_ming_yong"},"。"]]}],y=[{id:"pian_mu",term:"骈拇",pinyin:"pián mǔ",meaning:"脚趾相连（两趾并生为一）。骈：并生·连合，读 pián；拇：大拇趾。骈拇：两趾并生相连——天生的形体异常，多出于本性，却超出了正常德性的范围。"},{id:"zhi_zhi",term:"枝指",pinyin:"zhī zhǐ",meaning:"手上多生一指（旁生多余的手指）。枝：旁生·分枝；指：手指。枝指：旁生多余的手指——与骈拇并举，同为形体上多出的部分，出乎本性却侈于德。骈拇·枝指：两个形体意象并举，喻仁义之于道德，正如骈拇枝指之于正常形体——多出的、非本然的，看似出于本性，实则超出了道德的正轨。"},{id:"chu_hu_xing",term:"出乎性哉",pinyin:"chū hū xìng zāi",meaning:"（虽然）出于本性啊。出乎：出于·来自；性：本性·天性；哉：语气词，表承认。出乎性哉：虽然出于本性——庄子承认骈拇枝指·附赘县疣出于本性，但随即以「而侈于德/性」转折，指出出于本性不等于合于道德。（原文两处互文：骈拇枝指作「出乎性哉」，附赘县疣作「出乎形哉」，「性」「形」皆指本然。）"},{id:"chi_yu",term:"侈",pinyin:"chǐ",meaning:"超出·过多（超越正常范围）。侈：过多·超出，读 chǐ。侈于德：超出德性的正常范围；侈于性：超出本性的正常范围——「侈」是本节的核心判断词，骈拇枝指·附赘县疣·仁义多方，皆是「侈」——多出的、超出本然的，即非道德之正。"},{id:"fu_zhui",term:"附",pinyin:"fù",meaning:"附着·依附（多余附着之物）。附：附着。附赘县疣：附着的赘肉与悬挂的肉瘤——与骈拇枝指并举，皆是形体上多出的部分。"},{id:"zhui_xian",term:"赘县",pinyin:"zhuì xuán",meaning:"赘肉悬挂（多余下垂的肉）。赘：多余的肉·赘生物，读 zhuì；县：悬挂，通「悬」，读 xuán。赘县：赘肉悬挂——形体上多余下垂的赘生物。"},{id:"you_liu",term:"疣",pinyin:"yóu",meaning:"肉瘤·赘疣（皮肤上多余的突起）。疣：读 yóu，皮肤上多余的肉瘤·赘疣。附赘县疣：附着的赘肉·悬挂的肉瘤——与骈拇枝指并举，皆喻仁义之于道德，是多出的·非本然的赘生物。"},{id:"lie_pai",term:"列",pinyin:"liè",meaning:"排列·附列（附着于……之中）。列：排列·附列于。列于五藏哉：附列于五藏之中——仁义多方附列于五藏，如同骈拇枝指附列于形体，是多出的赘生物。"},{id:"wu_zang",term:"五藏",pinyin:"wǔ zàng",meaning:"五脏（心·肝·脾·肺·肾），此处喻人的内在本性。五藏：读 wǔ zàng，五脏——此处以五藏喻人的内在本性·德性之所在。多方乎仁义而用之者，列于五藏哉：以多方仁义附列于五藏（内在本性）之中——仁义多方附于本性，如骈拇附于足，是侈于德的赘生。"},{id:"fei_zhengdao",term:"非道德之正也",pinyin:"fēi dào dé zhī zhèng yě",meaning:"不是道德的正轨（本然之正）。非：不是；道德之正：道德的正轨·本然正道；也：语气词。而非道德之正也：而这不是道德的正轨——骈拇枝指·附赘县疣·仁义多方，皆非道德之正，是庄子批判仁义的核心判断。"},{id:"pian_zu",term:"骈于足者",pinyin:"pián yú zú zhě",meaning:"脚上并生（多余）的（肉）。骈于足：在脚上并生·连合；者：……的（东西）。骈于足者，连无用之肉也：脚上并生的，是连接无用的肉——以「无用之肉」点出骈拇的本质：多余·无用。"},{id:"pian_zhi_wu",term:"骈枝",pinyin:"pián zhī",meaning:"并生·旁枝（多余附生）。骈枝：骈拇与枝指的合称，泛指多余附生之物。多方骈枝于五藏之情者：在五藏本情上多方骈枝（多余附生）的——以骈枝喻仁义多方附于五藏本情之上。"},{id:"wu_zang_qing",term:"五藏之情",pinyin:"wǔ zàng zhī qíng",meaning:"五藏的本情（内在本性的真实状态）。五藏：五脏，喻内在本性；之情：的本情·真实状态。五藏之情：内在本性的真实状态——道德的本然，未被仁义多方附加之前的本真状态。"},{id:"yin_guo",term:"淫",pinyin:"yín",meaning:"过度·泛滥（超出本然的过度行为）。淫：过度·泛滥，读 yín。淫僻于仁义之行：在仁义的行为上过度偏僻——以「淫」指仁义之行的过度泛滥，超出道德本然。"},{id:"pi_pian",term:"僻",pinyin:"pì",meaning:"偏僻·偏离（偏离正道）。僻：偏僻·偏离，读 pì。淫僻：过度且偏离——淫是量的过度，僻是方向的偏离，两字合用，描绘仁义之行对道德本然的双重背离。"},{id:"renyi_xing",term:"仁义之行",pinyin:"rén yì zhī xíng",meaning:"仁义的行为（刻意推行仁义的作为）。仁义：儒家核心德目；之行：的行为·实践。淫僻于仁义之行：在仁义的行为上过度偏离——仁义之行本身即是对道德本然的「侈」，淫僻更是雪上加霜。"},{id:"duo_fan",term:"多",pinyin:"duō",meaning:"过多·繁多（超出本然的多）。多：过多·繁多。多方于聪明之用：在聪明的运用上过多繁方——以「多」指聪明运用的过度繁杂，超出本然。"},{id:"fang_fan",term:"方",pinyin:"fāng",meaning:"多方·繁方（多种方式·手段繁多）。方：方式·手段。多方：多种方式·手段繁多。多方于聪明之用：以多种方式繁用聪明——「多方」与「淫僻」并举，指仁义之行与聪明之用皆是对道德本然的过度干预。"},{id:"cong_ming_yong",term:"聪明之用也",pinyin:"cōng míng zhī yòng yě",meaning:"聪明（感官智识）的运用啊。聪：听觉灵敏；明：视觉明锐；之用：的运用。多方于聪明之用也：在聪明的运用上繁方过度——聪明（耳目感官·智识）的过度繁用，与仁义之行的淫僻并列，皆是骈枝于五藏之情的具体表现。淫僻于仁义之行·多方于聪明之用：两句并举收束——仁义（道德层面）的淫僻·聪明（智识层面）的多方，是多方骈枝于五藏之情的两个维度，皆非道德之正。"}],o=[{id:"si_s1",label:"骈于明者……而离朱是已",sentences:[[{text:"骈于明者",glossary:"pian_ming"},"，",{text:"乱",glossary:"luan_gan"},{text:"五色",glossary:"wu_se"},"，",{text:"淫",glossary:"yin_fan"},{text:"文章",glossary:"wen_zhang_se"},"，"],[{text:"青黄黼黻",glossary:"qing_huang_fu_fu"},"之",{text:"煌煌",glossary:"huang_huang"},{text:"非乎",glossary:"fei_hu"},"？而",{text:"离朱",glossary:"li_zhu"},"是已！"]]},{id:"si_s2",label:"多于聪者……而师旷是已",sentences:[["多于聪者，",{text:"乱",glossary:"luan_gan"},{text:"五声",glossary:"wu_sheng"},"，",{text:"淫",glossary:"yin_fan"},{text:"六律",glossary:"liu_lv"},"，"],[{text:"金石",glossary:"jin_shi_yue"},{text:"丝竹",glossary:"si_zhu_yue"},{text:"黄钟",glossary:"huang_zhong"},{text:"大吕",glossary:"da_lv"},"之声",{text:"非乎",glossary:"fei_hu"},"？而",{text:"师旷",glossary:"shi_kuang"},"是已！"]]},{id:"si_s3",label:"枝于仁者……而曾史是已",sentences:[[{text:"枝于仁者",glossary:"zhi_ren"},"，",{text:"擢德塞性",glossary:"zhuo_de_se_xing"},"以收名声，"],["使天下",{text:"簧鼓",glossary:"huang_gu"},"以",{text:"奉",glossary:"feng_buji"},"不及之法",{text:"非乎",glossary:"fei_hu"},"？而",{text:"曾",glossary:"zeng_shi"},"、",{text:"史",glossary:"zeng_shi"},"是已！"]]},{id:"si_s4",label:"骈于辩者……而杨墨是已",sentences:[["骈于辩者，",{text:"累瓦",glossary:"lei_wa"},{text:"结绳",glossary:"jie_sheng_bian"},{text:"窜句",glossary:"cuan_ju"},"，"],["游心于",{text:"坚白",glossary:"jian_bai"},{text:"同异",glossary:"tong_yi_bian"},"之间，而",{text:"敝",glossary:"bi_pi"},{text:"跬誉",glossary:"kui_yu"},"无用之言",{text:"非乎",glossary:"fei_hu"},"？而",{text:"杨",glossary:"yang_mo"},"、",{text:"墨",glossary:"yang_mo"},"是已！"]]},{id:"si_s5",label:"故此皆多骈旁枝之道……非天下之至正也",sentences:[["故此皆多骈",{text:"旁枝之道",glossary:"pang_zhi_dao"},"，",{text:"非天下之至正也",glossary:"zhi_zheng"},"。"]]}],m=[{id:"pian_ming",term:"骈于明者",pinyin:"pián yú míng zhě",meaning:"在视觉（明）上骈枝过度的人。骈：并生·过度，读 pián；明：视觉·目力。骈于明者：视觉过度发达的人——以「骈于明」对应上节「骈于足」，视觉过度即是目力的骈枝，代表离朱一类以目力超群自居者。"},{id:"luan_gan",term:"乱",pinyin:"luàn",meaning:"扰乱·搅乱（使本然秩序混乱）。乱：扰乱。乱五色·乱五声：扰乱五色的本然·扰乱五声的本然——骈于明者以过度目力扰乱色彩本然，多于聪者以过度听力扰乱声音本然。"},{id:"wu_se",term:"五色",pinyin:"wǔ sè",meaning:"五种基本色（青·黄·赤·白·黑）。五色：青·黄·赤·白·黑——色彩的本然，骈于明者以过度目力「乱五色」，以繁复文章「淫」之，超出本然。"},{id:"yin_fan",term:"淫",pinyin:"yín",meaning:"过度·泛滥（使之超出本然的过度繁用）。淫：过度·泛滥。淫文章·淫六律：过度繁用文章色彩·过度繁用六律音声——「淫」与「乱」并用，乱是扰乱秩序，淫是过度泛滥，两者共同描绘骈枝之害。"},{id:"wen_zhang_se",term:"文章",pinyin:"wén zhāng",meaning:"色彩花纹·纹饰（此处指视觉上的繁复纹饰）。文章：花纹·纹饰（非文章写作）。淫文章：过度繁用色彩纹饰——骈于明者以繁复纹饰炫耀目力，超出色彩本然。"},{id:"qing_huang_fu_fu",term:"青黄黼黻",pinyin:"qīng huáng fǔ fú",meaning:"青色·黄色·黼纹·黻纹（繁复华丽的色彩纹饰）。青黄：色彩；黼：斧形纹饰，读 fǔ；黻：亚形纹饰，读 fú。青黄黼黻：繁复华丽的色彩与纹饰——古代礼服上的华丽纹饰，此处喻骈于明者以繁复色彩纹饰炫耀目力之骈枝。"},{id:"huang_huang",term:"煌煌",pinyin:"huáng huáng",meaning:"光彩耀眼·华丽炫目的样子。煌煌：光彩夺目·华丽炫目。青黄黼黻之煌煌：青黄黼黻的华丽炫目——以「煌煌」形容繁复色彩的炫目，正是骈于明者「乱五色·淫文章」的结果。"},{id:"fei_hu",term:"非乎",pinyin:"fēi hū",meaning:"难道不是（……的骈枝）吗？非乎：难道不是——四次「非乎」反问，分别收束四类骈枝之人的描述，语气由反问转为确认：这难道不正是骈枝之道吗？"},{id:"li_zhu",term:"离朱",pinyin:"lí zhū",meaning:"传说中视力极强的人（能百步外见秋毫之末）。离朱：读 lí zhū，又称「离娄」，传说中目力超群者——庄子以离朱为「骈于明」的代表，视力过度发达，乱五色·淫文章，是目力的骈枝。"},{id:"wu_sheng",term:"五声",pinyin:"wǔ shēng",meaning:"五种基本音（宫·商·角·徵·羽）。五声：宫·商·角·徵·羽，读 wǔ shēng——音声的本然，多于聪者以过度听力「乱五声」，超出本然。"},{id:"liu_lv",term:"六律",pinyin:"liù lǜ",meaning:"六种律管（黄钟·太簇·姑洗·蕤宾·夷则·无射，古代音律标准）。六律：读 liù lǜ，古代音律的六个阳律——音律的本然标准，多于聪者以过度听力「淫六律」，泛滥繁用，超出本然。"},{id:"jin_shi_yue",term:"金石",pinyin:"jīn shí",meaning:"金属乐器·石制乐器（钟·磬等）。金：金属乐器（钟·铃等）；石：石制乐器（磬等）。金石：钟磬一类的乐器——古代八音（金·石·丝·竹·匏·土·革·木）中的两类。"},{id:"si_zhu_yue",term:"丝竹",pinyin:"sī zhú",meaning:"弦乐器·竹管乐器（琴瑟·笛箫等）。丝：弦乐器（琴·瑟等）；竹：竹管乐器（笛·箫等）。丝竹：弦乐与管乐——金石丝竹并举，泛指各类乐器，喻多于聪者以繁复乐器炫耀听力之骈枝。"},{id:"huang_zhong",term:"黄钟",pinyin:"huáng zhōng",meaning:"十二律中最基础的律（诸律之本）。黄钟：读 huáng zhōng，十二律之首，音最低沉浑厚，为诸律之本——此处与大吕并举，喻音律本然之正，被多于聪者淫乱。"},{id:"da_lv",term:"大吕",pinyin:"dà lǚ",meaning:"十二律中黄钟之次（阴律之首）。大吕：读 dà lǚ，十二律中紧随黄钟的阴律——黄钟·大吕并举，代表音律的本然标准，被多于聪者以过度聪明「淫」之，超出本然。"},{id:"shi_kuang",term:"师旷",pinyin:"shī kuàng",meaning:"春秋时期晋国著名乐师（传说天生目盲而听力极强）。师旷：读 shī kuàng，晋平公时的乐师，以听力超群·精通音律著称——庄子以师旷为「多于聪」的代表，听力过度发达，乱五声·淫六律，是听力的骈枝。"},{id:"zhi_ren",term:"枝于仁者",pinyin:"zhī yú rén zhě",meaning:"在仁上旁枝过度的人。枝：旁枝·多出，读 zhī；于仁：在仁上。枝于仁者：在仁上旁枝过度的人——以「枝于仁」对应「枝于手者，树无用之指」，仁的过度旁枝即是德性的赘生。"},{id:"zhuo_de_se_xing",term:"擢德塞性",pinyin:"zhuó dé sè xìng",meaning:"拔高德行·堵塞本性（强行拔高道德标准，反而堵塞了本性）。擢：拔高·提拔，读 zhuó；德：德行；塞：堵塞；性：本性。擢德塞性：强行拔高德行反而堵塞本性——枝于仁者以收名声为目的，强行拔高道德标准，反而堵塞了人的本然天性。"},{id:"huang_gu",term:"簧鼓",pinyin:"huáng gǔ",meaning:"以簧片·鼓声鼓动（比喻用花言巧语煽动蛊惑）。簧：簧片（乐器中的发声片），喻花言巧语；鼓：鼓动·煽动。簧鼓：以花言巧语鼓动煽惑——使天下簧鼓：使天下人被花言巧语鼓动，去奉行那不可企及的法则。"},{id:"feng_buji",term:"奉",pinyin:"fèng",meaning:"奉行·遵奉（强行遵奉）。奉：奉行·遵从。奉不及之法：奉行那不可企及的法则——「不及之法」是超出人本性所能企及的道德标准，枝于仁者以此强加于天下。"},{id:"zeng_shi",term:"曾·史",pinyin:"zēng · shǐ",meaning:"曾参·史鰌，儒家道德楷模。曾：曾参（曾子），读 zēng，孔子弟子，以孝道著称；史：史鰌（史鱼），读 shǐ，卫国大夫，以直谏著称。曾·史：儒家仁义道德的代表人物——庄子以曾·史为「枝于仁」的代表，擢德塞性·簧鼓天下，是仁义的骈枝。"},{id:"lei_wa",term:"累瓦",pinyin:"lěi wǎ",meaning:"堆砌瓦片（比喻堆砌论据·繁琐堆叠）。累：堆积；瓦：瓦片。累瓦：堆砌瓦片——喻骈于辩者以繁琐堆叠的论据构建辩论，如堆砌无用的瓦片。"},{id:"jie_sheng_bian",term:"结绳",pinyin:"jié shéng",meaning:"打结绳索（比喻以繁复逻辑缠绕纠结）。结绳：打结的绳索——喻骈于辩者以繁复逻辑缠绕纠结，如打结的绳索，令人难以解开。"},{id:"cuan_ju",term:"窜句",pinyin:"cuàn jù",meaning:"窜改·拼凑句子（以文字游戏拼凑论点）。窜：窜改·拼凑，读 cuàn；句：句子·论点。窜句：拼凑句子——喻骈于辩者以文字游戏拼凑论点。累瓦·结绳·窜句：三个意象并举，描绘骈于辩者的辩论手法——堆砌（累瓦）·缠绕（结绳）·拼凑（窜句），皆是无用的繁琐骈枝。"},{id:"jian_bai",term:"坚白",pinyin:"jiān bái",meaning:"「坚白论」（名家公孙龙的命题：坚·白·石三者可分离）。坚白：读 jiān bái，公孙龙「坚白石论」——以「坚」（触觉）·「白」（视觉）·「石」（实体）可分离为命题，是名家诡辩的代表。游心于坚白同异之间：沉迷于坚白·同异的名辩游戏之中。"},{id:"tong_yi_bian",term:"同异",pinyin:"tóng yì",meaning:"「同异论」（名家惠施的命题：万物同一·又各有差异）。同异：读 tóng yì，惠施「合同异」——以万物同一又各有差异为命题，是名家辩论的另一代表。坚白·同异：名家两大核心命题并举——庄子以此代表骈于辩者沉迷于无用名辩的骈枝之道。"},{id:"bi_pi",term:"敝",pinyin:"bì",meaning:"疲弊·耗尽（耗费精力于无用之事）。敝：疲弊·耗尽，读 bì。敝跬誉无用之言：耗尽精力于博取微小名誉的无用言辞——骈于辩者以繁琐辩论耗尽精力，只为博取微小名誉。"},{id:"kui_yu",term:"跬誉",pinyin:"kuǐ yù",meaning:"微小的名誉（半步之誉·极小的声誉）。跬：半步·极小，读 kuǐ；誉：名誉。跬誉：微小的名誉——以「跬」（半步）形容名誉之微小，骈于辩者耗尽精力（敝）只为博取这微小的名誉。"},{id:"yang_mo",term:"杨·墨",pinyin:"yáng · mò",meaning:"杨朱·墨翟，先秦两大思想家。杨：杨朱，读 yáng，主张「为我」·贵生；墨：墨翟，读 mò，主张「兼爱」·非攻。杨·墨：先秦与儒道并列的两大学派代表——庄子以杨·墨为「骈于辩」的代表，累瓦结绳·游心坚白同异，是辩论的骈枝。"},{id:"pang_zhi_dao",term:"旁枝之道",pinyin:"páng zhī zhī dào",meaning:"旁生枝节的道（偏离本然的旁枝末节之道）。旁枝：旁生的枝节·非主干；之道：的道。多骈旁枝之道：多出骈生的旁枝之道——以「旁枝」收束四类骈枝之人，呼应上节「骈枝」的核心意象。"},{id:"zhi_zheng",term:"非天下之至正也",pinyin:"fēi tiān xià zhī zhì zhèng yě",meaning:"不是天下最正的（本然之正）道。至正：最正·极致之正；也：语气词。非天下之至正也：不是天下最正的道——以「至正」收束全节，呼应上节「非道德之正」，四类骈枝之人（离朱·师旷·曾史·杨墨）皆非至正，皆是多骈旁枝之道。"}],p=[{id:"zheng_s1",label:"彼正正者……不失其性命之情",sentences:[[{text:"彼正正者",glossary:"bi_zheng_zheng"},"，不失其",{text:"性命之情",glossary:"xing_ming_qing"},"。"]]},{id:"zheng_s2",label:"故合者不为骈……短者不为不足",sentences:[["故",{text:"合者不为骈",glossary:"he_bu_pian"},"，而",{text:"枝者不为跂",glossary:"zhi_bu_qi"},"；"],["长者不为",{text:"有余",glossary:"you_yu_bu_zu"},"，短者不为",{text:"不足",glossary:"you_yu_bu_zu"},"。"]]},{id:"zheng_s3",label:"是故凫胫虽短……断之则悲",sentences:[["是故",{text:"凫胫",glossary:"fu_jing"},"虽短，",{text:"续之则忧",glossary:"xu_you"},"；"],[{text:"鹤胫虽长",glossary:"he_jing"},"，",{text:"断之则悲",glossary:"duan_bei"},"。"]]},{id:"zheng_s4",label:"故性长非所断……无所去忧也",sentences:[["故性长",{text:"非所断",glossary:"fei_suo_duan"},"，性短",{text:"非所续",glossary:"fei_suo_xu"},"，",{text:"无所去忧也",glossary:"wu_suo_qu_you"},"。"]]}],h=[{id:"bi_zheng_zheng",term:"彼正正者",pinyin:"bǐ zhèng zhèng zhě",meaning:"那真正端正（合于本然）的人。彼：那；正正：真正端正·本然之正（叠用加强）；者：……的人。彼正正者：那真正端正的人——与上节「非天下之至正」呼应，「正正者」是真正合于道德本然之正的人，非骈枝之人。"},{id:"xing_ming_qing",term:"性命之情",pinyin:"xìng mìng zhī qíng",meaning:"本性与天命的真实状态（本然的实情）。性：本性·天性；命：天命·自然赋予；之情：的真实状态·本情。性命之情：本性与天命的本然实情——是「正正者」的核心：不失本性与天命的本然状态，不增不减，不续不断。"},{id:"he_bu_pian",term:"合者不为骈",pinyin:"hé zhě bù wéi pián",meaning:"（天生）相合的不算是骈枝。合者：天生相合的（如骈拇两趾相连）；不为骈：不算是骈枝·不以为是多余。合者不为骈：天生相合的不视为骈枝——正正者以性命之情为准，天生相合即是本然，不以为异。"},{id:"zhi_bu_qi",term:"枝者不为跂",pinyin:"zhī zhě bù wéi qí",meaning:"（天生）旁枝的不算是多余。枝者：天生旁枝的（如枝指多出一指）；不为跂：不算是多余·不以为是赘生，读 qí（跂：多余·旁出）。枝者不为跂：天生旁枝的不视为多余——正正者顺应本然，天生旁枝亦是本性，不以为异。合者不为骈·枝者不为跂：两句并举，点出「正正者」的核心态度：顺应本然，不以本然之「合」为骈，不以本然之「枝」为跂——与上节批判骈拇枝指形成辩证：骈枝本身非错，错在「侈于德」的刻意为之。"},{id:"you_yu_bu_zu",term:"有余·不足",pinyin:"yǒu yú · bù zú",meaning:"多余·不足（超出或低于本然的评判）。有余：超出本然·多余；不足：低于本然·不足。长者不为有余·短者不为不足：长的不以为多余·短的不以为不足——正正者以本然为准，长短皆是本性，无所谓有余与不足。"},{id:"fu_jing",term:"凫胫",pinyin:"fú jìng",meaning:"野鸭的腿（天生短腿）。凫：野鸭，读 fú；胫：小腿，读 jìng。凫胫：野鸭的腿——天生短腿，是野鸭的本然，续之（接长）则忧，因违背本然。"},{id:"xu_you",term:"续之则忧",pinyin:"xù zhī zé yōu",meaning:"接续（加长）它就会忧苦。续：接续·加长；则：就；忧：忧苦·痛苦。凫胫虽短，续之则忧：野鸭腿虽短，接长它就会忧苦——以具体意象说明：违背本然（续短）即是痛苦之源。"},{id:"he_jing",term:"鹤胫虽长",pinyin:"hè jìng suī cháng",meaning:"鹤的腿虽然长。鹤：仙鹤；胫：小腿。鹤胫虽长：仙鹤腿虽长——天生长腿，是仙鹤的本然，断之（截短）则悲，因违背本然。凫胫·鹤胫：两个意象并举——一短一长，皆是本然，续短则忧·断长则悲，以极简的意象点出「性命之情」不可违背的道理。"},{id:"duan_bei",term:"断之则悲",pinyin:"duàn zhī zé bēi",meaning:"截断（缩短）它就会悲苦。断：截断·缩短；则：就；悲：悲苦·痛苦。鹤胫虽长，断之则悲：仙鹤腿虽长，截断它就会悲苦——违背本然（断长）即是悲苦之源。续之则忧·断之则悲：「忧」与「悲」对举——续短之忧·断长之悲，皆源于违背性命之情，是骈枝（续·断）的必然结果。"},{id:"fei_suo_duan",term:"非所断",pinyin:"fēi suǒ duàn",meaning:"不是应当截断的。非：不是；所断：应当截断之处。性长非所断：本性长的不是应当截断的——本然之长，顺应即是，断之违性。"},{id:"fei_suo_xu",term:"非所续",pinyin:"fēi suǒ xù",meaning:"不是应当接续的。非：不是；所续：应当接续之处。性短非所续：本性短的不是应当接续的——本然之短，顺应即是，续之违性。性长非所断·性短非所续：两句以「性」字领起，点出判断标准：以「性」（本然）为准，长短皆顺，断续皆非——呼应「彼正正者，不失其性命之情」。"},{id:"wu_suo_qu_you",term:"无所去忧也",pinyin:"wú suǒ qù yōu yě",meaning:"没有什么忧苦可以消除（本无忧苦）。无所：没有什么；去忧：消除忧苦；也：语气词。无所去忧也：本无忧苦可言——顺应性命之情（性长不断·性短不续），则本无忧苦，无需「去忧」，因为忧苦本就不存在。以「无所去忧」收束全节：正正者顺应本然，无续无断，故无忧无悲，本无忧苦可去——与「续之则忧·断之则悲」形成对比：违性则忧悲，顺性则无忧。"}],u=[{id:"ren_s1",label:"意仁义其非人情乎……彼仁人何其多忧也",sentences:[[{text:"意仁义",glossary:"yi_renyi"},"其非人情乎！",{text:"彼仁人",glossary:"bi_renren"},{text:"何其多忧也",glossary:"heqi_duoyou"},"。"]]},{id:"ren_s2",label:"且夫骈于拇者……其于忧一也",sentences:[["且夫骈于拇者，",{text:"决之",glossary:"jue_zhi"},"则泣；枝于手者，",{text:"齕之则啼",glossary:"he_ti"},"。"],["二者或有余于数，或不足于数，其于",{text:"忧一也",glossary:"you_yi"},"。"]]},{id:"ren_s3",label:"今世之仁人……决性命之情而饕贵富",sentences:[["今世之仁人，",{text:"蒿目",glossary:"hao_mu"},"而忧世之患；"],["不仁之人，决性命之情而",{text:"饕",glossary:"tao_tan"},{text:"贵富",glossary:"gui_fu"},"。"]]},{id:"ren_s4",label:"故意仁义其非人情乎……天下何其嚣嚣也",sentences:[["故",{text:"意仁义",glossary:"yi_renyi"},"其非人情乎！"],["自",{text:"三代以下者",glossary:"sandai_xia"},"，天下",{text:"何其嚣嚣也",glossary:"xiaoxiao"},"。"]]}],x=[{id:"yi_renyi",term:"意仁义",pinyin:"yì rén yì",meaning:"难道仁义……（表感叹·反问的发语词）。意：难道·岂，表反问·感叹，读 yì。意仁义其非人情乎：难道仁义不是人的本情吗！——以「意」领起反问，首尾呼应（本节开头与结尾各出现一次），强调仁义非人情的核心判断。"},{id:"bi_renren",term:"彼仁人",pinyin:"bǐ rén rén",meaning:"那些仁人（以仁义自居的人）。彼：那些；仁人：以仁义为志业的人。彼仁人：那些仁人——庄子以「彼」拉开距离，以旁观者视角审视仁人，指出其「多忧」的根本问题。"},{id:"heqi_duoyou",term:"何其多忧也",pinyin:"hé qí duō yōu yě",meaning:"为何如此多忧啊！何其：为何如此·多么；多忧：忧虑繁多；也：感叹语气。彼仁人何其多忧也：那些仁人为何如此多忧——仁人以仁义为志，反而忧患无穷，呼应上节「续之则忧·断之则悲」：以仁义「续」人情之「短」，故忧。"},{id:"jue_zhi",term:"决之",pinyin:"jué zhī",meaning:"剖开·割断它（骈拇相连之处）。决：剖开·割断，读 jué。骈于拇者，决之则泣：脚趾并生的，割断它就会哭泣——以「决骈拇」喻强行分离本然相合之物，违性则泣。"},{id:"he_ti",term:"齕之则啼",pinyin:"hé zhī zé tí",meaning:"咬断·截断它就会啼哭。齕：咬断·截断，读 hé；啼：啼哭·哭叫。枝于手者，齕之则啼：手上旁枝多指的，截断它就会啼哭——以「齕枝指」喻强行去除本然旁枝之物，违性则啼。决之则泣·齕之则啼：「泣」与「啼」对举——决骈拇之泣·齕枝指之啼，皆因违背本然（性命之情）而生，呼应上节「续之则忧·断之则悲」，以四字（忧·悲·泣·啼）层层叠加，强调违性之苦。"},{id:"you_yi",term:"忧一也",pinyin:"yōu yī yě",meaning:"忧苦是同一的（忧苦并无二致）。忧：忧苦；一：同一·一样；也：语气词。其于忧一也：就忧苦而言是同一的——骈拇（有余于数）与枝指（不足于数）虽一多一少，但被决·被齕的忧苦是相同的，因为两者皆是违背本然。"},{id:"hao_mu",term:"蒿目",pinyin:"hāo mù",meaning:"极目远望·眼睛因忧虑而枯槁（忧世之状）。蒿：枯槁·极力，读 hāo；目：眼睛·目光。蒿目：极目远望·目光枯槁——形容仁人忧世之深，眼睛因忧虑而枯槁，极目四望，满眼皆是世之患。蒿目而忧世之患：枯槁着眼神忧虑世间的祸患——仁人以仁义为志，反而忧患无穷，正是「何其多忧」的具体写照。"},{id:"tao_tan",term:"饕",pinyin:"tāo",meaning:"贪婪·贪求（贪得无厌）。饕：贪婪，读 tāo（饕餮之「饕」）。饕贵富：贪婪地追求富贵——不仁之人决性命之情，以贪婪追求富贵，与仁人「蒿目忧世」形成对比，两者皆是违背性命之情。"},{id:"gui_fu",term:"贵富",pinyin:"guì fù",meaning:"富贵·权贵与财富。贵：权贵·地位；富：财富。饕贵富：贪婪地追求权贵与财富——不仁之人以「饕贵富」违背性命之情，与仁人以「仁义」违背性命之情，两者皆非人情之本然。蒿目忧世·饕贵富：仁人与不仁之人并举——一忧世（以仁义骈枝）·一饕富（以贪欲骈枝），两者皆「决性命之情」，皆非人情之正，故「意仁义其非人情乎」首尾呼应。"},{id:"sandai_xia",term:"三代以下者",pinyin:"sān dài yǐ xià zhě",meaning:"三代（夏·商·周）以后的时代。三代：夏·商·周三代，古代理想的治世；以下：以后·之后；者：……的（时代）。自三代以下者：自三代以后——三代是庄子心目中尚近本然的时代，三代以下则仁义大行·嚣嚣不止，是道德本然失落的历史起点。"},{id:"xiaoxiao",term:"何其嚣嚣也",pinyin:"hé qí xiāo xiāo yě",meaning:"为何如此喧嚣纷乱啊！何其：为何如此·多么；嚣嚣：喧嚣纷乱·吵嚷不休，读 xiāo xiāo；也：感叹语气。天下何其嚣嚣也：天下为何如此喧嚣纷乱——三代以下，仁义大行，仁人多忧·不仁者饕贵富，天下因此嚣嚣不止。何其多忧·何其嚣嚣：两个「何其」首尾呼应——仁人之「多忧」与天下之「嚣嚣」，皆源于仁义非人情·违背性命之情的根本问题。"}],_=[{id:"chang_s1",label:"且夫待钩绳规矩而正者……此失其常然也",sentences:[["且夫",{text:"待",glossary:"dai_xu"},{text:"钩绳",glossary:"gou_sheng"},{text:"规矩",glossary:"gui_ju"},"而正者，是",{text:"削其性者也",glossary:"xiao_xing"},"；"],["待绳约",{text:"胶漆",glossary:"jiao_qi"},"而固者，是",{text:"侵",glossary:"qin_de"},"其德者也；"],[{text:"屈折礼乐",glossary:"qu_zhe_liyue"},"，",{text:"呴俞仁义",glossary:"xu_yu_renyi"},"，以",{text:"慰",glossary:"wei_xin"},"天下之心者，此",{text:"失",glossary:"shi_chang"},"其",{text:"常然",glossary:"chang_ran"},"也。"]]},{id:"chang_s2",label:"天下有常然……约束不以纆索",sentences:[["天下有",{text:"常然",glossary:"chang_ran"},"。常然者，"],[{text:"曲者不以钩",glossary:"qu_gou"},"，",{text:"直者不以绳",glossary:"zhi_sheng"},"，"],[{text:"圆者不以规",glossary:"yuan_gui"},"，",{text:"方者不以矩",glossary:"fang_ju"},"，"],[{text:"附离",glossary:"fu_li"},"不以",{text:"胶漆",glossary:"jiao_qi"},"，",{text:"约束",glossary:"yue_shu"},"不以",{text:"纆索",glossary:"mo_suo"},"。"]]},{id:"chang_s3",label:"故天下诱然皆生……不可亏也",sentences:[["故天下",{text:"诱然皆生",glossary:"you_ran_sheng"},"，而不知其所以生；"],[{text:"同焉皆得",glossary:"tong_yan_de"},"，而不知其所以得。"],["故",{text:"古今不二",glossary:"gujin_bu_er"},"，",{text:"不可亏也",glossary:"bu_ke_kui"},"。"]]},{id:"chang_s4",label:"则仁义又奚连连……使天下惑也",sentences:[["则仁义又",{text:"奚",glossary:"xi_hewei"},"连连如",{text:"胶漆纆索",glossary:"jiao_mo_suo"},"而游乎道德之间为哉！"],["使天下",{text:"惑也",glossary:"huo_ye"},"！"]]}],b=[{id:"dai_xu",term:"待",pinyin:"dài",meaning:"依赖·等待（需要借助外力）。待：依赖·需要。待钩绳规矩而正者：需要依赖钩绳规矩才能端正的——「待」点出问题所在：需要外力（钩绳规矩·胶漆·礼乐仁义）才能端正·固定·安慰，正是违背本然的标志。"},{id:"gou_sheng",term:"钩绳",pinyin:"gōu shéng",meaning:"钩尺·墨绳（测量曲直的工具）。钩：钩尺，测量弯曲的工具；绳：墨绳·墨线，测量直线的工具。钩绳：测量曲直的工具——喻以外在标准（仁义礼乐）强行矫正本然。"},{id:"gui_ju",term:"规矩",pinyin:"guī jǔ",meaning:"圆规·矩尺（测量圆方的工具）。规：圆规，画圆的工具；矩：矩尺，画方的工具。规矩：测量圆方的工具——与钩绳并举，喻外在规范标准。待钩绳规矩而正者：需要钩绳规矩才能端正——本然之曲·直·圆·方无需工具，需要工具才能「正」，正是削其性的表现。"},{id:"xiao_xing",term:"削其性者也",pinyin:"xuē qí xìng zhě yě",meaning:"是削减（损害）本性的人啊。削：削减·损害，读 xuē；其性：本性。削其性者也：是损害本性的——待钩绳规矩而正，需外力矫正，正是对本性的削减损害。"},{id:"jiao_qi",term:"胶漆",pinyin:"jiāo qī",meaning:"胶水·漆（粘合固定的材料）。胶：胶水；漆：漆料。胶漆：粘合固定之物——喻以外在强制（礼乐仁义）粘合固定人心，违背本然。待绳约胶漆而固者·连连如胶漆纆索：两处出现，前喻侵其德，后喻仁义强行粘附于道德之间。"},{id:"qin_de",term:"侵",pinyin:"qīn",meaning:"侵害·侵蚀（损害本然）。侵：侵害·侵蚀。侵其德者也：是侵害德性的——待胶漆而固，需外力粘合，正是对德性的侵害。削其性·侵其德：「削」与「侵」对举——削是削减本性，侵是侵害德性，两者皆是外力干预本然的结果。"},{id:"qu_zhe_liyue",term:"屈折礼乐",pinyin:"qū zhé lǐ yuè",meaning:"以礼乐屈折（扭曲）人心。屈折：屈曲折弯·强行扭曲；礼乐：礼制与音乐（儒家教化的核心手段）。屈折礼乐：以礼乐强行屈折人心——以礼乐扭曲人的本然，如以钩绳强行矫正曲直。"},{id:"xu_yu_renyi",term:"呴俞仁义",pinyin:"xǔ yú rén yì",meaning:"以仁义柔声抚慰（哄骗安抚）。呴俞：柔声抚慰·哄骗，读 xǔ yú（呴：吹气·柔声；俞：应声·顺从）。呴俞仁义：以仁义柔声哄骗抚慰——以温柔的仁义话语抚慰人心，实则是对本然的扭曲。屈折礼乐·呴俞仁义：两句并举——礼乐是强行屈折（硬的一面），仁义是柔声抚慰（软的一面），一硬一软，皆是「失其常然」的手段。"},{id:"wei_xin",term:"慰",pinyin:"wèi",meaning:"安慰·抚慰（以外力安抚人心）。慰：安慰·抚慰。以慰天下之心者：用来安慰天下人的心——以礼乐仁义安慰天下之心，看似善意，实则是「失其常然」。"},{id:"shi_chang",term:"失",pinyin:"shī",meaning:"失去·丧失（丧失本然）。失：失去·丧失。失其常然：丧失了本然——待外力而正·固·慰，皆是「失其常然」的表现。"},{id:"chang_ran",term:"常然",pinyin:"cháng rán",meaning:"本然常态（万物本来如此的自然状态）。常：恒常·本来；然：如此·状态。常然：本来如此的自然状态——本节核心概念，天下万物各有其常然：曲·直·圆·方·附离·约束，皆有本然，无需外力。"},{id:"qu_gou",term:"曲者不以钩",pinyin:"qū zhě bù yǐ gōu",meaning:"弯曲的（本然如此）不需要钩尺（来矫正）。曲者：弯曲的（本然之曲）；不以钩：不需要钩尺。曲者不以钩：本然弯曲的不需要钩尺——本然之曲即是其常然，无需钩尺矫正。"},{id:"zhi_sheng",term:"直者不以绳",pinyin:"zhí zhě bù yǐ shéng",meaning:"笔直的（本然如此）不需要墨绳（来校正）。直者：笔直的（本然之直）；不以绳：不需要墨绳。直者不以绳：本然笔直的不需要墨绳——本然之直即是其常然，无需墨绳校正。"},{id:"yuan_gui",term:"圆者不以规",pinyin:"yuán zhě bù yǐ guī",meaning:"圆的（本然如此）不需要圆规（来画定）。圆者：圆的（本然之圆）；不以规：不需要圆规。圆者不以规：本然之圆不需要圆规。"},{id:"fang_ju",term:"方者不以矩",pinyin:"fāng zhě bù yǐ jǔ",meaning:"方的（本然如此）不需要矩尺（来量定）。方者：方的（本然之方）；不以矩：不需要矩尺。方者不以矩：本然之方不需要矩尺。曲·直·圆·方四句并举：四种本然形态，各有其常然，皆无需外在工具（钩·绳·规·矩）矫正——喻万物本性各有其常然，无需礼乐仁义的外力干预。"},{id:"fu_li",term:"附离",pinyin:"fù lí",meaning:"附着·依附（本然相合之物）。附离：附着·依附，本然相合在一起的。附离不以胶漆：本然相附的不需要胶漆——本然相合之物无需胶漆粘合，喻人与人·人与道的本然相合无需仁义强行粘附。"},{id:"yue_shu",term:"约束",pinyin:"yuē shù",meaning:"约束·束缚（本然相聚之物）。约束：约束·聚合在一起。约束不以纆索：本然相聚的不需要纆索——本然相聚之物无需绳索捆绑，喻人与道的本然相聚无需礼乐强行束缚。附离·约束：两句并举——附离（合）不以胶漆·约束（聚）不以纆索，本然的合与聚皆无需外力，呼应「待胶漆而固者，是侵其德者也」。"},{id:"mo_suo",term:"纆索",pinyin:"mò suǒ",meaning:"绳索·捆绑之绳。纆：绳索，读 mò；索：绳子。纆索：绳索——喻以礼乐仁义强行捆绑束缚人心，违背本然。胶漆·纆索：两个意象贯穿本节——胶漆喻粘合固定（侵德），纆索喻捆绑束缚（失常然），合称喻仁义礼乐对道德本然的强行干预。"},{id:"you_ran_sheng",term:"诱然皆生",pinyin:"yòu rán jiē shēng",meaning:"自然而然地都生长（无知无觉地自然生发）。诱然：自然而然·悠然自得，读 yòu rán；皆生：都生长。天下诱然皆生，而不知其所以生：天下万物自然而然地生长，却不知道为何能生长——万物顺应常然，自然生发，无需知晓原因，无需外力干预。"},{id:"tong_yan_de",term:"同焉皆得",pinyin:"tóng yān jiē dé",meaning:"同样地都各有所得（无知无觉地各得其所）。同焉：同样地·一同；皆得：都各有所得。同焉皆得，而不知其所以得：同样地都各有所得，却不知道为何能得——万物顺应常然，各得其所，无需知晓原因。诱然皆生·同焉皆得：两句并举——生与得皆是本然常然的自然结果，「不知其所以」正是常然的特征：无为而自然，无需知晓，无需干预。"},{id:"gujin_bu_er",term:"古今不二",pinyin:"gǔ jīn bù èr",meaning:"古今如一·始终不变（常然恒常不变）。古今：古代与今日；不二：不变·如一。古今不二：古今如一，始终不变——常然是恒常的，不因时代而改变，呼应「常然」的「常」字。"},{id:"bu_ke_kui",term:"不可亏也",pinyin:"bù kě kuī yě",meaning:"不可损亏（不可减损）。亏：损亏·减损，读 kuī；也：语气词。不可亏也：不可损亏——常然古今不二，不可损亏，任何外力干预（钩绳规矩·胶漆纆索·礼乐仁义）皆是对常然的损亏。古今不二·不可亏也：两句收束「常然」的论述——常然恒常不变，不可损亏，是天下万物的根本，仁义礼乐的干预正是对这不可亏损之常然的破坏。"},{id:"xi_hewei",term:"奚",pinyin:"xī",meaning:"为何·何必（表反问）。奚：为何·何必，读 xī。则仁义又奚连连如胶漆纆索而游乎道德之间为哉：那么仁义又为何连连如胶漆纆索般游荡于道德之间呢——以「奚」领起反问，否定仁义强行附于道德之间的必要性。"},{id:"jiao_mo_suo",term:"胶漆纆索",pinyin:"jiāo qī mò suǒ",meaning:"胶漆与纆索（强行粘附捆绑之物）。胶漆：粘合之物；纆索：捆绑之绳。连连如胶漆纆索：连连不断如胶漆纆索般——以胶漆纆索喻仁义强行粘附于道德之间，无法脱离，正是对道德常然的侵害。"},{id:"huo_ye",term:"惑也",pinyin:"huò yě",meaning:"迷惑（天下）啊。惑：迷惑·蒙蔽；也：感叹语气。使天下惑也：使天下人迷惑——仁义如胶漆纆索游于道德之间，使天下人迷失本然，不知常然，故惑。以「使天下惑也」收束全节，呼应上节「天下何其嚣嚣也」：嚣嚣是仁义惑天下的结果，惑是嚣嚣的根源——仁义以胶漆纆索强附于道德，使天下失其常然，故惑·故嚣嚣。"}],z=[{id:"yu_s1",label:"夫小惑易方……大惑易性",sentences:[["夫",{text:"小惑易方",glossary:"xiao_huo_fang"},"，",{text:"大惑易性",glossary:"da_huo_xing"},"。"]]},{id:"yu_s2",label:"何以知其然邪……天下莫不奔命于仁义",sentences:[["何以知其然邪？自",{text:"虞氏",glossary:"yu_shi"},{text:"招仁义",glossary:"zhao_renyi"},"以",{text:"挠",glossary:"nao_tian"},"天下也，天下莫不",{text:"奔命",glossary:"ben_ming"},"于仁义。"]]},{id:"yu_s3",label:"是非以仁义易其性与",sentences:[["是非以仁义",{text:"易其性与",glossary:"yi_qi_xing"},"？"]]}],c=[{id:"xiao_huo_fang",term:"小惑易方",pinyin:"xiǎo huò yì fāng",meaning:"小的迷惑改变方向（迷失方位）。小惑：小的迷惑；易：改变；方：方向·方位。小惑易方：小的迷惑只是改变了方向——迷失方向尚可找回，是小害。"},{id:"da_huo_xing",term:"大惑易性",pinyin:"dà huò yì xìng",meaning:"大的迷惑改变本性（丧失本然）。大惑：大的迷惑；易：改变·替换；性：本性。大惑易性：大的迷惑改变了本性——本性一旦改变，则无可挽回，是大害。小惑易方·大惑易性：两句对举，以「小惑·大惑」的程度递进，引出仁义招惑天下·易天下之性的核心批判。"},{id:"yu_shi",term:"虞氏",pinyin:"yú shì",meaning:"虞舜（舜帝）。虞氏：读 yú shì，即舜，上古圣王之一，儒家推崇的仁义典范——庄子以虞氏为仁义招惑天下的历史起点，指出正是舜「招仁义」，使天下开始以仁义易其性。"},{id:"zhao_renyi",term:"招仁义",pinyin:"zhāo rén yì",meaning:"招引·标榜仁义（以仁义为旗帜号召天下）。招：招引·标榜·倡导；仁义：儒家核心德目。招仁义：以仁义为旗帜号召天下——虞氏招仁义，是仁义大行于天下的历史起点，呼应上节「自三代以下者，天下何其嚣嚣也」。"},{id:"nao_tian",term:"挠",pinyin:"náo",meaning:"扰乱·搅扰（扰乱本然）。挠：扰乱·搅扰，读 náo。以挠天下也：用来扰乱天下——虞氏以仁义招惑，扰乱了天下本然的常然状态。"},{id:"ben_ming",term:"奔命",pinyin:"bēn mìng",meaning:"奔走效命（拼命追逐）。奔：奔走；命：效命·追逐。奔命于仁义：拼命奔走追逐仁义——天下莫不奔命于仁义：天下没有人不拼命追逐仁义，正是「大惑易性」的具体表现。"},{id:"yi_qi_xing",term:"易其性与",pinyin:"yì qí xìng yú",meaning:"改变（替换）了本性吗？易：改变·替换；其性：本性；与：语气词，表反问。是非以仁义易其性与：这难道不是以仁义改变了本性吗——以反问收束，确认仁义招惑天下·易性的判断，呼应「大惑易性」。"}],f=[{id:"xun_s1",label:"故尝试论之……天下莫不以物易其性矣",sentences:[["故尝试论之：自",{text:"三代以下者",glossary:"xun_sandai"},"，天下莫不以物",{text:"易其性矣",glossary:"xun_yi_xing"},"！"]]},{id:"xun_s2",label:"小人则以身殉利……圣人则以身殉天下",sentences:[["小人则",{text:"以身殉利",glossary:"xun_li"},"；"],["士则以身殉名；"],["大夫则以身殉家；"],["圣人则以身殉天下。"]]},{id:"xun_s3",label:"故此数子者……伤性以身为殉一也",sentences:[["故此数子者，事业不同，",{text:"名声异号",glossary:"mingsheng_yihao"},"，其于",{text:"伤性",glossary:"shang_xing"},"以身为",{text:"殉",glossary:"xun_wei"},"，",{text:"一也",glossary:"xun_yi_ye"},"。"]]}],q=[{id:"xun_sandai",term:"三代以下者",pinyin:"sān dài yǐ xià zhě",meaning:"三代（夏·商·周）以后的时代。三代以下：夏商周以后——呼应上节「自三代以下者，天下何其嚣嚣也」，以「三代以下」为仁义大行·以物易性的历史起点。"},{id:"xun_yi_xing",term:"易其性矣",pinyin:"yì qí xìng yǐ",meaning:"改变（替换）了本性啊。易：改变·替换；其性：本性；矣：感叹语气。天下莫不以物易其性矣：天下没有人不以外物改变了本性——以「物」（外物·名利家国天下）易性，是三代以下天下人的共同命运，呼应上节「以仁义易其性」。"},{id:"xun_li",term:"以身殉利",pinyin:"yǐ shēn xùn lì",meaning:"以自身（本性）殉葬于利（为利而牺牲本性）。以身：以自身·以本性；殉：殉葬·为……而牺牲，读 xùn；利：利益。以身殉利：为利益而牺牲自身本性——小人以身殉利，是「以物易其性」的最低层。"},{id:"mingsheng_yihao",term:"名声异号",pinyin:"míng shēng yì hào",meaning:"名声称号各不相同。名声：声名·名誉；异号：不同的称号。名声异号：名声称号各异——小人·士·大夫·圣人，名声称号各不相同，但「伤性以身为殉」是相同的。"},{id:"shang_xing",term:"伤性",pinyin:"shāng xìng",meaning:"伤害本性（损伤本然之性）。伤：伤害·损伤；性：本性。伤性：伤害本性——四类人（小人·士·大夫·圣人）皆以身殉（利·名·家·天下），皆是伤性，皆是以物易其性。"},{id:"xun_wei",term:"殉",pinyin:"xùn",meaning:"殉葬·为……而牺牲（以自身本性为代价）。殉：读 xùn，殉葬·为某物而牺牲。以身为殉：以自身（本性）为殉葬之物——四类人皆以身（本性）殉葬于各自追逐之物（利·名·家·天下），是「易其性」的最终形态。"},{id:"xun_yi_ye",term:"一也",pinyin:"yī yě",meaning:"是同一的（本质相同）。一：同一·一样；也：语气词。其于伤性以身为殉，一也：就伤性以身为殉而言，是同一的——四类人事业不同·名声异号，但伤性以身为殉的本质是相同的，呼应上节「其于忧一也」，以「一也」收束，是庄子论证的核心句式。"}],k=[{id:"zang_s1",label:"臧与谷……俱亡其羊",sentences:[[{text:"臧",glossary:"zang_gu"},"与",{text:"谷",glossary:"zang_gu"},"，二人相与牧羊而俱",{text:"亡其羊",glossary:"wang_yang"},"。"]]},{id:"zang_s2",label:"问臧奚事……博塞以游",sentences:[["问臧",{text:"奚",glossary:"xi_he"},"事，则",{text:"挟策",glossary:"xie_ce"},"读书；"],["问谷奚事，则",{text:"博塞",glossary:"bo_sai"},"以游。"]]},{id:"zang_s3",label:"二人者……亡羊均也",sentences:[["二人者，事业不同，其于",{text:"亡羊",glossary:"wang_yang"},{text:"均也",glossary:"jun_ye"},"。"]]}],j=[{id:"zang_gu",term:"臧·谷",pinyin:"zāng · gǔ",meaning:"两个牧羊人的名字（寓言人物）。臧：读 zāng；谷：读 gǔ。臧·谷：庄子寓言中的两个牧羊人——一读书·一博塞，事业不同，却同样亡羊，喻上节「事业不同·伤性一也」的具体寓言化。"},{id:"wang_yang",term:"亡其羊",pinyin:"wáng qí yáng",meaning:"丢失了各自的羊。亡：丢失·失去，读 wáng；其羊：各自的羊。俱亡其羊：两人都丢失了羊——「亡羊」是本节的核心意象，喻人丧失本性（亡其性命之情），呼应全篇「伤性·易性」的主题。"},{id:"xi_he",term:"奚",pinyin:"xī",meaning:"何·做什么（疑问词）。奚：何·什么，读 xī。问臧奚事：问臧在做什么——以「奚」引出两人各自所为，为「事业不同」作铺垫。"},{id:"xie_ce",term:"挟策",pinyin:"xié cè",meaning:"夹着竹简（读书·求学）。挟：夹持·携带；策：竹简·书册，读 cè。挟策读书：夹着竹简读书——臧以读书（求名·求学）为事，是「士以身殉名」的寓言化，看似高雅，实则与博塞同样亡羊（伤性）。"},{id:"bo_sai",term:"博塞",pinyin:"bó sài",meaning:"一种古代博弈游戏（赌博·玩耍）。博塞：读 bó sài，古代一种棋类博弈游戏，类似掷骰赌博。博塞以游：以博塞游戏为乐——谷以博塞（求乐·逐利）为事，是「小人以身殉利」的寓言化。挟策读书·博塞以游：两者对举——一雅一俗·一名一利，正是「事业不同」的具体写照，却同样亡羊，喻无论高雅还是低俗的追求，皆是伤性。"},{id:"jun_ye",term:"均也",pinyin:"jūn yě",meaning:"是相同的·一样的。均：相同·一样，读 jūn；也：语气词。其于亡羊均也：就亡羊而言是相同的——事业不同，亡羊相同，是本节的核心判断，呼应上节「伤性以身为殉，一也」。均也·一也：两节收束句并举——「一也」（七节）·「均也」（八节），庄子以两个寓言·两个「相同」的判断，层层强化：无论名号如何不同，伤性（亡羊）的本质是相同的。"}],w=[{id:"boyi_s1",label:"伯夷死名于首阳之下……盗跖死利于东陵之上",sentences:[[{text:"伯夷",glossary:"bo_yi"},"死名于",{text:"首阳",glossary:"shou_yang"},"之下，"],[{text:"盗跖",glossary:"dao_zhi"},"死利于",{text:"东陵",glossary:"dong_ling"},"之上。"]]},{id:"boyi_s2",label:"二人者……残生伤性均也",sentences:[["二人者，所死不同，其于",{text:"残生伤性",glossary:"can_shang"},{text:"均也",glossary:"boyi_jun"},"。"]]},{id:"boyi_s3",label:"奚必伯夷之是而盗跖之非乎",sentences:[[{text:"奚必",glossary:"xi_bi"},{text:"伯夷之是",glossary:"zhi_shi_fei"},"而",{text:"盗跖之非",glossary:"zhi_shi_fei"},"乎？"]]}],P=[{id:"bo_yi",term:"伯夷",pinyin:"bó yī",meaning:"商末周初的贤人（以守节·死名著称）。伯夷：读 bó yī，商末孤竹君之子，周武王伐纣后，耻食周粟，饿死于首阳山——儒家推崇的道德楷模，以「死名」（为名节而死）为世人称颂。庄子以伯夷与盗跖并举，指出两者残生伤性之本质相同。"},{id:"shou_yang",term:"首阳",pinyin:"shǒu yáng",meaning:"首阳山（伯夷饿死之处）。首阳：读 shǒu yáng，山名，相传在今山西省，伯夷·叔齐不食周粟，饿死于此。死名于首阳之下：为名节而死于首阳山下——「首阳」是伯夷死名的具体地点，以地名强化历史真实感。"},{id:"dao_zhi",term:"盗跖",pinyin:"dào zhí",meaning:"传说中的大盗（以逐利·死利著称）。盗跖：读 dào zhí，传说中春秋时期的大盗，率众横行天下，以「死利」（为利益而死）为世人唾弃——庄子以盗跖与伯夷并举，以最高尚（伯夷）与最卑劣（盗跖）的对比，点出残生伤性均也的核心判断。"},{id:"dong_ling",term:"东陵",pinyin:"dōng líng",meaning:"东陵（盗跖死利之处）。东陵：读 dōng líng，地名，盗跖死于此处。死利于东陵之上：为利益而死于东陵之上——「东陵」与「首阳」对举，一上一下·一名一利，地点不同·所死不同，残生伤性相同。"},{id:"can_shang",term:"残生伤性",pinyin:"cán shēng shāng xìng",meaning:"残害生命·伤损本性。残：残害·损害；生：生命；伤：伤损；性：本性。残生伤性：残害生命·伤损本性——是本节对「死名·死利」的本质判断，呼应前节「伤性以身为殉」，以「残生」加重语气：不仅伤性，更是残害生命。"},{id:"boyi_jun",term:"均也",pinyin:"jūn yě",meaning:"是相同的·一样的。均：相同·一样；也：语气词。残生伤性均也：残生伤性是相同的——呼应八节「亡羊均也」·七节「伤性以身为殉，一也」，以「均也」三度收束，层层强化：无论死名还是死利，残生伤性的本质相同。"},{id:"xi_bi",term:"奚必",pinyin:"xī bì",meaning:"何必·为何一定（表反问·否定必然性）。奚：何·为何；必：一定·必然。奚必：何必·为何一定——以「奚必」引起反问，否定世俗以伯夷为是·盗跖为非的价值判断。"},{id:"zhi_shi_fei",term:"之是·之非",pinyin:"zhī shì · zhī fēi",meaning:"以……为是·以……为非（世俗的是非判断）。之是：以之为是·认为是对的；之非：以之为非·认为是错的。伯夷之是而盗跖之非：以伯夷为是而以盗跖为非——世俗的是非判断，庄子以「奚必」反问否定之：残生伤性均也，何必以伯夷为是·盗跖为非？"}],T=[{id:"jin_s1",label:"天下尽殉也……则俗谓之小人",sentences:[["天下",{text:"尽殉也",glossary:"jin_xun"},"：",{text:"彼",glossary:"bi_qi"},{text:"其",glossary:"bi_qi"},"所殉仁义也，则俗谓之君子；"],["其所殉货财也，则俗谓之小人。"]]},{id:"jin_s2",label:"其殉一也……有小人焉",sentences:[[{text:"其殉一也",glossary:"xun_yi_ye"},"，则有君子焉，有小人焉。"]]},{id:"jin_s3",label:"若其残生损性……又恶取君子小人于其间哉",sentences:[["若其残生损性，则","盗跖亦伯夷已，又",{text:"恶",glossary:"wu_qu"},{text:"取",glossary:"wu_qu"},"君子小人",{text:"于其间哉",glossary:"yu_qi_jian"},"！"]]}],v=[{id:"jin_xun",term:"尽殉也",pinyin:"jìn xùn yě",meaning:"都在以身为殉啊。尽：全部·都；殉：以身为殉·为某物牺牲本性，读 xùn；也：感叹语气。天下尽殉也：天下人都在以身为殉——以「尽」字总括天下，是本节的总领句，承接七节「天下莫不以物易其性」，将「以物易性」具体化为「殉」。"},{id:"bi_qi",term:"彼·其",pinyin:"bǐ · qí",meaning:"那些人·他们（泛指天下殉者）。彼：那些人；其：他们的。彼其所殉：那些人所殉的——「彼其」连用，指天下尽殉之人，以「所殉」的不同（仁义·货财）区分君子·小人。"},{id:"xun_yi_ye",term:"其殉一也",pinyin:"qí xùn yī yě",meaning:"他们以身为殉是相同的。其殉：他们的殉；一：相同·一样；也：语气词。其殉一也：殉的本质是相同的——君子殉仁义·小人殉货财，殉的对象不同，殉的本质（残生伤性）相同，呼应七节「一也」·八节「均也」·九节「均也」，是《骈拇》全篇「一也·均也」系列的第四次收束。"},{id:"wu_qu",term:"恶·取",pinyin:"wū · qǔ",meaning:"何处·取得（从哪里区分）。恶：何处·哪里，读 wū（疑问词）；取：取得·区分。又恶取：又从哪里区分——又恶取君子小人于其间哉：又从哪里去区分其中的君子与小人呢？"},{id:"yu_qi_jian",term:"于其间哉",pinyin:"yú qí jiān zāi",meaning:"在其中（区分君子小人）呢！于：在；其间：其中·彼此之间；哉：反问语气。又恶取君子小人于其间哉：又怎么能在其中区分出君子与小人呢——以反问收束全节：残生损性均也，君子·小人的区分本无意义，盗跖亦伯夷，伯夷亦盗跖，世俗是非判断彻底瓦解。"}],G=[{id:"zang11_s1",label:"且夫属其性乎仁义者……非吾所谓明也",sentences:[["且夫",{text:"属",glossary:"shu_xing"},"其",{text:"性",glossary:"shu_xing"},"乎仁义者，虽",{text:"通",glossary:"tong_ru"},"如",{text:"曾",glossary:"zeng_shi_11"},"、",{text:"史",glossary:"zeng_shi_11"},"，非吾所谓",{text:"臧",glossary:"zang_yi"},"也；"],["属其性于",{text:"五味",glossary:"wu_wei"},"，虽通如",{text:"俞儿",glossary:"yu_er"},"，非吾所谓臧也；"],["属其性乎五声，虽通如",{text:"师旷",glossary:"shikuang_11"},"，非吾所谓",{text:"聪",glossary:"cong_yi"},"也；"],["属其性乎五色，虽通如",{text:"离朱",glossary:"lizhu_11"},"，非吾所谓",{text:"明",glossary:"ming_yi"},"也。"]]},{id:"zang11_s2",label:"吾所谓臧者……任其性命之情而已矣",sentences:[["吾所谓",{text:"臧者",glossary:"zang_zhe"},"，非所谓",{text:"仁义之谓也",glossary:"renyi_wei"},"，",{text:"臧于其德",glossary:"zang_de"},"而已矣；"],["吾所谓臧者，非所谓仁义之谓也，",{text:"任",glossary:"ren_xing"},"其",{text:"性命之情",glossary:"xingming_qing_11"},{text:"而已矣",glossary:"eryiyi"},"；"]]},{id:"zang11_s3",label:"吾所谓聪者……自见而已矣",sentences:[["吾所谓聪者，非谓其",{text:"闻彼",glossary:"wen_bi"},"也，",{text:"自闻",glossary:"zi_wen"},"而已矣；"],["吾所谓明者，非谓其",{text:"见彼",glossary:"jian_bi"},"也，",{text:"自见",glossary:"zi_jian"},"而已矣。"]]},{id:"zang11_s4",label:"夫不自见而见彼……适人之适而不自适其适者也",sentences:[["夫",{text:"不自见而见彼",glossary:"bu_zi_jian"},"，",{text:"不自得而得彼者",glossary:"bu_zi_de"},"，"],["是",{text:"得人之得而不自得其得",glossary:"de_ren_de"},"者也，"],[{text:"适人之适而不自适其适",glossary:"shi_ren_shi"},"者也。"]]},{id:"zang11_s5",label:"夫适人之适而不自适其适……是同为淫僻也",sentences:[["夫适人之适而不自适其适，虽盗跖与伯夷，是同为",{text:"淫僻也",glossary:"yin_pi_11"},"。"]]},{id:"zang11_s6",label:"余愧乎道德……而下不敢为淫僻之行也",sentences:[[{text:"余",glossary:"yu_wo"},{text:"愧乎道德",glossary:"kui_dao"},"，",{text:"是以上",glossary:"shi_yi_shang"},"不敢为",{text:"仁义之操",glossary:"renyi_cao"},"，而下不敢为",{text:"淫僻之行也",glossary:"yin_pi_xing"},"。"]]}],C=[{id:"shu_xing",term:"属·性",pinyin:"shǔ · xìng",meaning:"附属·系属（将本性附系于……）。属：附属·系属·归属，读 shǔ；性：本性。属其性乎仁义：将本性附系于仁义——「属性于……」是本节的核心句式，以「属」点出问题：将本性外附于仁义·五味·五声·五色，正是「以物易性」的具体形态。"},{id:"tong_ru",term:"通",pinyin:"tōng",meaning:"精通·通达（在某领域极为精通）。通：精通·通达。虽通如曾史：即使精通如曾参·史鰌——「虽通……非吾所谓……」是本节的反复句式，以「虽通」承认其才能，以「非吾所谓」否定其本质：精通不等于本然之臧·聪·明。"},{id:"zeng_shi_11",term:"曾·史",pinyin:"zēng · shǐ",meaning:"曾参·史鰌（儒家仁义道德的代表）。曾：曾参（曾子），读 zēng；史：史鰌（史鱼），读 shǐ——呼应第二节「枝于仁者……曾·史是已」，此处再次以曾·史为「属性于仁义」的代表，指出即使精通如曾·史，亦非吾所谓臧。"},{id:"zang_yi",term:"臧",pinyin:"zāng",meaning:"善·好（本然之善·本真之好）。臧：善·好，读 zāng。非吾所谓臧也：不是我所说的善——「臧」是本节庄子自定义的核心概念，非世俗之善（仁义·五味·五声·五色），而是本然之善（臧于其德·任其性命之情）。"},{id:"wu_wei",term:"五味",pinyin:"wǔ wèi",meaning:"五种基本味（酸·苦·甘·辛·咸）。五味：酸·苦·甘·辛·咸——味觉的本然，属性于五味者以过度味觉骈枝，与属性于五声·五色并举，皆是将本性外附于感官享受。"},{id:"yu_er",term:"俞儿",pinyin:"yú ér",meaning:"传说中味觉极为敏锐的人（善辨五味者）。俞儿：读 yú ér，传说中能辨别各种味道的味觉达人——与师旷（五声）·离朱（五色）并举，是「属性于五味」的代表，虽通如俞儿，亦非吾所谓臧。"},{id:"shikuang_11",term:"师旷",pinyin:"shī kuàng",meaning:"春秋晋国著名乐师（以听力超群著称）。师旷：读 shī kuàng——呼应第二节「多于聪者……师旷是已」，此处再次以师旷为「属性于五声」的代表，虽通如师旷，亦非吾所谓聪。"},{id:"cong_yi",term:"聪",pinyin:"cōng",meaning:"聪（本然之聪·自闻之聪）。聪：听觉灵敏·聪慧，读 cōng。非吾所谓聪也：不是我所说的聪——庄子重新定义「聪」：非闻彼（听外物），而是自闻（听本然之声），呼应「吾所谓聪者，非谓其闻彼也，自闻而已矣」。"},{id:"lizhu_11",term:"离朱",pinyin:"lí zhū",meaning:"传说中视力极强的人（能百步外见秋毫之末）。离朱：读 lí zhū——呼应第二节「骈于明者……离朱是已」，此处再次以离朱为「属性于五色」的代表，虽通如离朱，亦非吾所谓明。"},{id:"ming_yi",term:"明",pinyin:"míng",meaning:"明（本然之明·自见之明）。明：视觉明锐·明察，读 míng。非吾所谓明也：不是我所说的明——庄子重新定义「明」：非见彼（见外物），而是自见（见本然之真），呼应「吾所谓明者，非谓其见彼也，自见而已矣」。"},{id:"zang_zhe",term:"臧者",pinyin:"zāng zhě",meaning:"我所说的善（本然之善的定义）。臧者：我所说的善·好——庄子以「吾所谓臧者」自定义，与世俗之臧（仁义·五味）区分，给出两个定义：臧于其德·任其性命之情。"},{id:"renyi_wei",term:"仁义之谓也",pinyin:"rén yì zhī wèi yě",meaning:"所说的仁义（世俗定义的仁义之善）。之谓：所说的·所指的。非所谓仁义之谓也：不是所说的仁义那种意思——庄子以「非所谓……之谓也」句式，明确区分自己的定义与世俗定义。"},{id:"zang_de",term:"臧于其德",pinyin:"zāng yú qí dé",meaning:"善于（守护）本然之德（德性的本真状态）。臧：善·好；于其德：在本然之德上。臧于其德而已矣：善于守护本然之德罢了——「臧」的第一个定义：不是仁义，而是守护德性的本然。"},{id:"ren_xing",term:"任",pinyin:"rèn",meaning:"顺任·听任（顺应本然，不加干预）。任：顺任·听任，读 rèn。任其性命之情：顺任本性与天命的本然实情——「臧」的第二个定义：不是仁义，而是顺任性命之情，呼应第三节「彼正正者，不失其性命之情」。"},{id:"xingming_qing_11",term:"性命之情",pinyin:"xìng mìng zhī qíng",meaning:"本性与天命的本然实情。性：本性；命：天命；之情：的本然实情——呼应第三节「性命之情」，是《骈拇》全篇的核心概念，此处作为「臧」的最终定义：任其性命之情而已矣。"},{id:"eryiyi",term:"而已矣",pinyin:"ér yǐ yǐ",meaning:"罢了·如此而已（收束·强调简洁）。而已矣：罢了——本节四次「而已矣」（臧于其德·任性命之情·自闻·自见），以「而已矣」收束每个定义，强调本然之简：无需外附，顺任本然即是。"},{id:"wen_bi",term:"闻彼",pinyin:"wén bǐ",meaning:"听闻外物（以耳力感知外在之声）。闻：听闻；彼：外物·他者。非谓其闻彼也：不是说能听闻外物——「闻彼」是世俗之聪（如师旷），庄子否定之。"},{id:"zi_wen",term:"自闻",pinyin:"zì wén",meaning:"自己听闻本然（听闻自身本性之声）。自闻：自己听闻·听闻本然。自闻而已矣：听闻自身本然罢了——「聪」的定义：非闻彼（外），而是自闻（内·本然）。"},{id:"jian_bi",term:"见彼",pinyin:"jiàn bǐ",meaning:"看见外物（以目力感知外在之色）。见：看见；彼：外物·他者。非谓其见彼也：不是说能看见外物——「见彼」是世俗之明（如离朱），庄子否定之。"},{id:"zi_jian",term:"自见",pinyin:"zì jiàn",meaning:"自己看见本然（见自身本性之真）。自见：自己看见·见本然。自见而已矣：看见自身本然罢了——「明」的定义：非见彼（外），而是自见（内·本然）。闻彼·自闻·见彼·自见：四组「彼·自」对举，构成本节核心辩证：外（彼）vs 内（自），世俗之聪明 vs 本然之聪明。"},{id:"bu_zi_jian",term:"不自见而见彼",pinyin:"bù zì jiàn ér jiàn bǐ",meaning:"不看见自身本然却去看见外物。不自见：不看见自身；见彼：看见外物。不自见而见彼：舍内求外——以「不自见」领起，点出问题：舍弃自身本然，转而追求外物之见。"},{id:"bu_zi_de",term:"不自得而得彼者",pinyin:"bù zì dé ér dé bǐ zhě",meaning:"不自得本然却去得外物的人。不自得：不得自身本然；得彼：得外物·他者之得。不自得而得彼者：舍自得而求外得的人——与「不自见而见彼」并举，两句共同描绘「属性于外」的本质：舍内求外。"},{id:"de_ren_de",term:"得人之得而不自得其得",pinyin:"dé rén zhī dé ér bù zì dé qí dé",meaning:"得到别人的所得却得不到自己本然的所得。得人之得：得到别人的所得（外得）；不自得其得：得不到自己本然的所得（内得·本然之得）。得人之得而不自得其得：以外得替代内得——以繁复的「得」字重叠，强调「得」的两种形态：外得（人之得）vs 内得（自得其得），外得再多，亦非本然之得。"},{id:"shi_ren_shi",term:"适人之适而不自适其适",pinyin:"shì rén zhī shì ér bù zì shì qí shì",meaning:"适合别人的所适却不能自适本然的所适。适：适合·适意·安适，读 shì；适人之适：适合别人的所适（外适）；不自适其适：不能自适本然的所适（内适·本然之适）。适人之适而不自适其适：以外适替代内适——与「得人之得而不自得其得」并举，以「得·适」两组繁复重叠，强调：外得·外适皆是舍本逐末，本然之得·本然之适才是「自得·自适」。"},{id:"yin_pi_11",term:"淫僻也",pinyin:"yín pì yě",meaning:"过度偏邪（违背本然的过度偏离）。淫：过度；僻：偏邪。是同为淫僻也：都同样是淫僻——呼应第一节「淫僻于仁义之行」，此处以「淫僻」收束「适人之适」的论述：盗跖与伯夷，若皆适人之适而不自适，则同为淫僻，无论名号高下。"},{id:"yu_wo",term:"余",pinyin:"yú",meaning:"我（庄子自称）。余：我，读 yú——庄子以第一人称「余」收束全篇，由论他人转为自述，是《骈拇》全篇唯一的自述句。"},{id:"kui_dao",term:"愧乎道德",pinyin:"kuì hū dào dé",meaning:"对道德感到惭愧（以道德为准绳而自省）。愧：惭愧·自省；乎：对于；道德：道与德（本然之道德，非仁义之道德）。余愧乎道德：我对道德感到惭愧——庄子以「愧乎道德」自省，以道德（本然）为标准，既不敢为仁义之操，也不敢为淫僻之行。"},{id:"shi_yi_shang",term:"是以上",pinyin:"shì yǐ shàng",meaning:"因此在上（从高处说）。是以：因此；上：在上·就高而言。是以上不敢为仁义之操：因此在上不敢以仁义为操守——「上·下」对举：上指高处（仁义之名），下指低处（淫僻之行），两者皆不敢为。"},{id:"renyi_cao",term:"仁义之操",pinyin:"rén yì zhī cāo",meaning:"以仁义为操守（标榜仁义的行为准则）。操：操守·行为准则，读 cāo。仁义之操：以仁义为操守——庄子不敢为仁义之操，因仁义是「属性于外·适人之适」，是淫僻的高端形态。"},{id:"yin_pi_xing",term:"淫僻之行也",pinyin:"yín pì zhī xíng yě",meaning:"淫僻的行为（过度偏邪的行为）。淫僻：过度偏邪；之行：的行为。不敢为淫僻之行：不敢做淫僻的行为——庄子不敢为淫僻之行，因淫僻是「适人之适」的低端形态。仁义之操·淫僻之行：上·下对举收束——仁义（上·高名）与淫僻（下·低行），在「适人之适而不自适其适」的本质上是相同的（同为淫僻），庄子两者皆不敢为，以「愧乎道德」自守本然。"}];return(E,n)=>{const D=g("DaoReadingPrelude"),t=g("DaoTextReading"),s=g("DaoKeywordCards"),r=g("DaoLineGuide");return V(),N("div",null,[n[0]||(n[0]=l("",3)),a(D,{title:"从骈拇枝指到自见自得，理解外篇的第一个批判",summary:"《骈拇》是外篇第一篇，也是从内篇进入外篇的第一步。内篇七篇是庄子思想的核心建构；外篇则是对内篇核心思想的展开与应用。《骈拇》选择从批判仁义入手：仁义聪明，就像骈拇枝指——多余的赘生物。全篇最终落到「自闻·自见·自适其适」：听见自己的声音，看见自己的本性，按自己的本性生活。",points:[{label:"先看",text:"顺着骈拇之喻、四类骈枝、凫胫鹤胫、臧谷亡羊、自见自得这条线走一遍。"},{label:"再问",text:"庄子批判仁义，是否等于提倡为所欲为？"},{label:"最后",text:"「自适其适」与「适人之适」，差别在哪里？"}],hint:"本篇是外篇的起点。读的时候可以不断回看内篇《应帝王》，两篇是同一个批判的两种表达。"}),n[1]||(n[1]=i("h2",{id:"一、骈拇枝指之喻·仁义多方侈于德",tabindex:"-1"},[e("一、骈拇枝指之喻·仁义多方侈于德 "),i("a",{class:"header-anchor",href:"#一、骈拇枝指之喻·仁义多方侈于德","aria-label":'Permalink to "一、骈拇枝指之喻·仁义多方侈于德"'},"​")],-1)),n[2]||(n[2]=i("h3",{id:"原文",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:d,glossary:y,"default-mode":"classic","aria-label":"骈拇·骈拇枝指之喻 原文"}),n[3]||(n[3]=i("h3",{id:"字词释义",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(s,{items:[{term:"骈拇",pinyin:["pián","mǔ"],meaning:"骈：并连；拇：大拇趾。脚趾并连多生。"},{term:"枝指",pinyin:["zhī","zhǐ"],meaning:"枝：多生；指：手指。手上多生一指。"},{term:"出乎性哉",pinyin:["chū","hū","xìng","zāi"],meaning:"虽出于天生本性（非人为造成）。"},{term:"侈于德",pinyin:["chǐ","yú","dé"],meaning:"侈：多余、过分。对于德而言是多余的。"},{term:"附赘县疣",pinyin:["fù","zhuì","xuán","yóu"],meaning:"附赘：附着的赘肉；县疣：悬挂的肉瘤。身体上多余的赘生物。"},{term:"侈于性",pinyin:["chǐ","yú","xìng"],meaning:"对于本性而言是多余的。"},{term:"多方乎仁义",pinyin:["duō","fāng","hū","rén","yì"],meaning:"多方：多方面、繁多；用多种方式推行仁义。"},{term:"列于五藏",pinyin:["wǔ","zàng"],meaning:"五藏：五脏，喻内心深处。深植于内心。"},{term:"非道德之正",pinyin:["fēi","dào","dé","zhī","zhèng"],meaning:"不是道德的正道。"},{term:"淫僻于仁义",pinyin:["yín","pì","yú","rén","yì"],meaning:"淫僻：过度偏邪。在仁义的行为上过度偏邪。"}]}),n[4]||(n[4]=i("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"骈拇枝指，是多余的——哪怕天生的，也是多余的",subtitle:"天生，不等于正当；自然生长，不等于符合本性。",lines:[{text:"骈拇枝指出乎性哉，而侈于德。",tone:"立喻",guide:"《骈拇》开篇，庄子用一个极具冲击力的比喻：骈拇——脚上两趾并连，天生如此；枝指——手上多生一指，天生如此。这两者，不是人为造成的，是天生的——「出乎性哉」——出于本性，出于自然。但庄子说：侈于德——对于「德」而言，是多余的。这里有一个关键的区分：性——天生的自然状态（包括骈拇枝指）；德——本真的、完整的存在状态。骈拇枝指，虽然是天生的，但它是对本真完整状态的偏离——多了，就是多余，哪怕是天生的多余。"},{text:"多方乎仁义而用之者，列于五藏哉，而非道德之正也。",tone:"转折",guide:"第三句，是全段的核心转折——庄子把骈拇枝指的逻辑，直接套用到仁义上：多方推行仁义，深植于内心——这，不是道德的正道。这句话的力度，在于类比的精准：骈拇枝指——天生，但多余；仁义多方——深植，但非正道。仁义，就像骈拇枝指——不是说它是坏的，而是说它是「多余的」——是对道德本真状态的偏离，是「侈于德」。"}]}),n[5]||(n[5]=i("h2",{id:"二、四类骈枝之人·离朱·师旷·曾史·杨墨",tabindex:"-1"},[e("二、四类骈枝之人·离朱·师旷·曾史·杨墨 "),i("a",{class:"header-anchor",href:"#二、四类骈枝之人·离朱·师旷·曾史·杨墨","aria-label":'Permalink to "二、四类骈枝之人·离朱·师旷·曾史·杨墨"'},"​")],-1)),n[6]||(n[6]=i("h3",{id:"原文-1",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:o,glossary:m,"default-mode":"classic","aria-label":"骈拇·四类骈枝之人 原文"}),n[7]||(n[7]=i("h3",{id:"字词释义-1",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义-1","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(s,{items:[{term:"骈于明",pinyin:["pián","yú","míng"],meaning:"在视觉上骈枝（过度执着于视觉之明）。"},{term:"乱五色",pinyin:["luàn","wǔ","sè"],meaning:"扰乱五色（青黄赤白黑）的自然状态。"},{term:"淫文章",pinyin:["yín","wén","zhāng"],meaning:"淫：过度；文章：纹饰花样。过度追求纹饰华美。"},{term:"黼黻",pinyin:["fǔ","fú"],meaning:"古代礼服上的花纹，斧形为黼，亚形为黻。"},{term:"离朱",pinyin:["lí","zhū"],meaning:"传说中视力极佳的人，能百步之外见秋毫之末。"},{term:"多于聪",pinyin:["duō","yú","cōng"],meaning:"在听觉上多余（过度执着于听觉之聪）。"},{term:"乱五声",pinyin:["luàn","wǔ","shēng"],meaning:"扰乱五声（宫商角徵羽）的自然状态。"},{term:"淫六律",pinyin:["yín","liù","lǜ"],meaning:"过度追求六律的精妙（六律：古代音律标准）。"},{term:"师旷",pinyin:["shī","kuàng"],meaning:"春秋时晋国著名乐师，听觉极为敏锐。"},{term:"枝于仁",pinyin:["zhī","yú","rén"],meaning:"在仁上多生枝节（过度执着于仁）。"},{term:"擢德塞性",pinyin:["zhuó","dé","sāi","xìng"],meaning:"擢：拔高、强行提升；塞：堵塞。强行拔高德行、堵塞本性。"},{term:"簧鼓",pinyin:["huáng","gǔ"],meaning:"簧：簧片（乐器）；鼓：鼓动。用花言巧语鼓动。"},{term:"骈于辩",pinyin:["pián","yú","biàn"],meaning:"在辩论上骈枝（过度执着于辩才）。"},{term:"坚白同异",pinyin:["jiān","bái","tóng","yì"],meaning:"名家的命题：坚白石之辩（公孙龙）·同异之辩（惠施）。"}]}),n[8]||(n[8]=i("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"四类骈枝：越明越乱，越聪越乱，越仁越伤性，越辩越偏",subtitle:"天赋本身不是问题，执着于把天赋发挥到极致，才是骈枝。",lines:[{text:"骈于明者，乱五色，淫文章，青黄黼黻之煌煌非乎？而离朱是已！",tone:"离朱",guide:"离朱——传说中视力最强的人，百步外见秋毫之末。庄子说：这样的「明」，是骈枝——乱五色（扰乱了五色的自然状态），淫文章（过度追求纹饰的华美）。离朱的眼力，是天赋——但他执着于用这个天赋，把视觉之「明」发挥到极致——结果，不是看见了更多的真实，而是被色彩与纹饰所迷乱。越明，越乱——这是骈于明的悖论。"},{text:"枝于仁者，擢德塞性以收名声，使天下簧鼓以奉不及之法非乎？而曾、史是已！",tone:"曾史",guide:"曾参——孔子弟子，以孝著称；史鱼——卫国大夫，以直著称。庄子说：这样的「仁」，是枝节——擢德塞性（强行拔高德行、堵塞本性），收名声（以此收取名声），使天下簧鼓以奉不及之法（用花言巧语鼓动天下人，去奉行那些人力难以企及的法则）。这里，庄子的批判最为犀利：「擢德塞性」——强行「拔高」德行，本身就是在「堵塞」本性——仁义，不是从本性自然流出的，而是被「擢」出来的——越擢越高，本性越被堵塞。「使天下簧鼓以奉不及之法」——用花言巧语鼓动天下人，去奉行那些人力根本难以企及的标准——这不是帮助天下，而是给天下制造焦虑与枷锁。越仁，越伤性——这是枝于仁的悖论。"},{text:"故此皆多骈旁枝之道，非天下之至正也。",tone:"总结",guide:"庄子的结论，简洁而有力：这些，都是多余骈枝、旁生枝节之道——不是天下最正确的道。「至正」——最正确的道，不是最聪明的，不是最有才能的，不是最仁义的——而是顺应本性，不多不少，不骈不枝。"}]}),n[9]||(n[9]=i("h2",{id:"三、正正者·性命之情·凫胫鹤胫",tabindex:"-1"},[e("三、正正者·性命之情·凫胫鹤胫 "),i("a",{class:"header-anchor",href:"#三、正正者·性命之情·凫胫鹤胫","aria-label":'Permalink to "三、正正者·性命之情·凫胫鹤胫"'},"​")],-1)),n[10]||(n[10]=i("h3",{id:"原文-2",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:p,glossary:h,"default-mode":"classic","aria-label":"骈拇·凫胫鹤胫 原文"}),n[11]||(n[11]=i("h3",{id:"字词释义-2",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义-2","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(s,{items:[{term:"正正者",pinyin:["zhèng","zhèng","zhě"],meaning:"真正端正的人。重叠强调。"},{term:"性命之情",pinyin:["xìng","mìng","zhī","qíng"],meaning:"性：本性；命：天命；情：实情、本真。本性与天命的真实状态。"},{term:"合者不为骈",pinyin:["hé","zhě"],meaning:"合：合并、连接。天生连在一起的，不算骈枝。"},{term:"枝者不为跂",pinyin:["zhī","qí"],meaning:"枝：多生；跂：多余的脚趾。天生多出的，不算多余之跂。"},{term:"凫胫虽短",pinyin:["fú","jìng"],meaning:"凫：野鸭；胫：小腿。野鸭的腿虽然短。"},{term:"续之则忧",pinyin:["xù","zhī","zé","yōu"],meaning:"续：接长。若强行接长，反而造成忧患。"},{term:"无所去忧也",pinyin:["wú","suǒ","qù","yōu","yě"],meaning:"这样就没有什么忧患可以去除了（本就无忧）。"}]}),n[12]||(n[12]=i("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"凫胫虽短，续之则忧；鹤胫虽长，断之则悲",subtitle:"忧患，是强行改变本性之后才产生的。",lines:[{text:"彼正正者，不失其性命之情。",tone:"正论",guide:"经过前两段对骈枝的批判，第三段庄子给出正面答案——正正者（真正端正的人）——不失其性命之情——不失去本性与天命的真实状态。这一句，是《骈拇》全篇的核心命题：什么是「正」？不是仁义，不是聪明，不是辩才——而是不失性命之情——保持本性与天命的真实状态，不多不少，不增不减。"},{text:"凫胫虽短，续之则忧；鹤胫虽长，断之则悲。故性长非所断，性短非所续，无所去忧也。",tone:"凫胫鹤胫",guide:"《骈拇》最著名的比喻——凫胫鹤胫：野鸭的腿虽然短，如果强行接长，反而造成忧患；鹤的腿虽然长，如果强行截断，反而造成悲苦。性长非所断，性短非所续——天性长的，不是用来截断的；天性短的，不是用来接长的——无所去忧也——顺应本性，本就没有忧患——忧患，是强行改变本性之后才产生的。这个比喻，是对前两段批判的完美收尾：离朱的明——是鹤胫，强行截断（用仁义规范它）则悲；师旷的聪——是鹤胫，强行截断则悲；曾史的仁——是凫胫，强行接长（擢德）则忧；杨墨的辩——是凫胫，强行接长则忧。但更深的一层是：每个人的本性，都是自己的凫胫或鹤胫——不需要被接长，不需要被截断，顺应本性，就是「正正者」。仁义礼乐，就是那个强行接长凫胫、截断鹤胫的手术刀——出于善意，但造成忧悲。"}]}),n[13]||(n[13]=i("h2",{id:"四、仁义非人情·仁人多忧·三代以下嚣嚣",tabindex:"-1"},[e("四、仁义非人情·仁人多忧·三代以下嚣嚣 "),i("a",{class:"header-anchor",href:"#四、仁义非人情·仁人多忧·三代以下嚣嚣","aria-label":'Permalink to "四、仁义非人情·仁人多忧·三代以下嚣嚣"'},"​")],-1)),n[14]||(n[14]=i("h3",{id:"原文-3",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:u,glossary:x,"default-mode":"classic","aria-label":"骈拇·仁义非人情 原文"}),n[15]||(n[15]=i("h3",{id:"字词释义-3",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义-3","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(s,{items:[{term:"意",pinyin:["yì"],meaning:"通「抑」，表推测语气：莫非、难道。"},{term:"人情",pinyin:["rén","qíng"],meaning:"人的真实本情、自然情感。"},{term:"决之则泣",pinyin:["jué","zhī","zé","qì"],meaning:"决：割断。割断骈趾则哭泣。"},{term:"齕之则啼",pinyin:["hé","zhī","zé","tí"],meaning:"齕：咬断、切除。切除枝指则啼哭。"},{term:"其于忧一也",pinyin:["qí","yú","yōu","yī","yě"],meaning:"在忧患这件事上是一样的。"},{term:"蒿目",pinyin:["hāo","mù"],meaning:"蒿：草名，茎细；蒿目：眼睛因忧虑而细如蒿茎，即愁眉苦脸。"},{term:"决性命之情",pinyin:["jué","xìng","mìng","zhī","qíng"],meaning:"割裂、破坏本性与天命的真实状态。"},{term:"饕贵富",pinyin:["tāo","guì","fù"],meaning:"饕：贪婪。贪婪地追求富贵。"},{term:"嚣嚣",pinyin:["áo","áo"],meaning:"喧嚣纷扰、争竞不休的样子。"}]}),n[16]||(n[16]=i("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"意仁义其非人情乎！彼仁人何其多忧也",subtitle:"多忧，正是因为仁义不是本情——是强行接长的凫胫，所以忧。",lines:[{text:"意仁义其非人情乎！彼仁人何其多忧也。",tone:"反问",guide:"庄子在第三段用凫胫鹤胫收尾之后，第四段以一个反问开篇——莫非仁义，根本就不是人的真实本情？那些推行仁义的人，为何如此多忧？这个问题，是《骈拇》从「喻」转向「论」的关键转折。前三段，庄子用比喻说明仁义是骈枝——第四段，庄子用仁人的实际状态来证明：如果仁义真的是人的本情，推行仁义应该是自然而然、轻松愉快的——为什么仁人反而「多忧」？多忧，正是因为仁义不是本情——是强行接长的凫胫，所以忧；是强行截断的鹤胫，所以悲。"},{text:"今世之仁人，蒿目而忧世之患；不仁之人，决性命之情而饕贵富。",tone:"两类人",guide:"庄子用两类人做对比：仁人——蒿目而忧世之患——愁眉苦脸，忧虑天下的祸患——仁义，给他带来的是无尽的忧虑；不仁之人——决性命之情而饕贵富——割裂本性，贪婪地追求富贵——贪欲，给他带来的是对本性的破坏。两类人，一个执着于仁义，一个执着于富贵——表面上截然相反，实质上完全一样：都在「决性命之情」——都在割裂本性。仁人割裂本性，是为了仁义；不仁之人割裂本性，是为了富贵——割裂的方式不同，割裂本性这件事，是一样的。"},{text:"故意仁义其非人情乎！自三代以下者，天下何其嚣嚣也。",tone:"历史",guide:"庄子再次重申反问，然后给出历史判断：自三代（夏商周）以下——天下何其嚣嚣！嚣嚣——喧嚣纷扰，争竞不休——三代以下，仁义礼乐大行其道——结果不是天下太平，而是天下嚣嚣——争名的争名，争利的争利，仁人忧世，不仁者饕富——这，难道不正是仁义非人情的最好证明吗？"}]}),n[17]||(n[17]=i("h2",{id:"五、天下有常然·胶漆纆索·仁义惑天下",tabindex:"-1"},[e("五、天下有常然·胶漆纆索·仁义惑天下 "),i("a",{class:"header-anchor",href:"#五、天下有常然·胶漆纆索·仁义惑天下","aria-label":'Permalink to "五、天下有常然·胶漆纆索·仁义惑天下"'},"​")],-1)),n[18]||(n[18]=i("h3",{id:"原文-4",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-4","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:_,glossary:b,"default-mode":"classic","aria-label":"骈拇·天下有常然 原文"}),n[19]||(n[19]=i("h3",{id:"字词释义-4",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义-4","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(s,{items:[{term:"钩绳规矩",pinyin:["gōu","shéng","guī","jǔ"],meaning:"钩：曲尺；绳：墨线；规：圆规；矩：方尺。木工量度工具。"},{term:"削其性",pinyin:["xuē","qí","xìng"],meaning:"削：削减、损伤。损伤了本性。"},{term:"绳约胶漆",pinyin:["shéng","yuē","jiāo","qī"],meaning:"绳约：绳索捆绑；胶漆：胶水与漆。捆绑与粘合的工具。"},{term:"侵其德",pinyin:["qīn","qí","dé"],meaning:"侵害了本真之德。"},{term:"屈折礼乐",pinyin:["qū","zhé","lǐ","yuè"],meaning:"屈折：扭曲、强迫。强行用礼乐来扭曲（人的本性）。"},{term:"呴俞仁义",pinyin:["xǔ","yú","rén","yì"],meaning:"呴俞：和颜悦色、温言软语地劝诱。用仁义来温言劝诱。"},{term:"常然",pinyin:["cháng","rán"],meaning:"自然而然的常态，本来如此的状态。"},{term:"纆索",pinyin:["mò","suǒ"],meaning:"纆索：绳索。自然约束，不需要绳索捆绑。"},{term:"诱然皆生",pinyin:["yòu","rán"],meaning:"诱然：自然而然、顺畅地。自然而然地生长。"}]}),n[20]||(n[20]=i("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"天下有常然——万物本来如此，不需要任何外在工具",subtitle:"礼乐仁义，就是那套多余的工具。",lines:[{text:"待钩绳规矩而正者，是削其性者也；待绳约胶漆而固者，是侵其德者也。",tone:"工具",guide:"庄子用木工工具作比喻：需要钩绳规矩才能端正的——说明它本来就不是那个形状——强行让它「正」，是在削减它的本性；需要绳约胶漆才能固定的——说明它本来就不是那样连接的——强行让它「固」，是在侵害它的本真之德。这两句，是对礼乐仁义最精准的批判：礼乐仁义，就是那套钩绳规矩胶漆纆索——用来让人「端正」、「固定」——但这个「端正」，是削其性；这个「固定」，是侵其德。"},{text:"天下有常然。常然者，曲者不以钩，直者不以绳，圆者不以规，方者不以矩，附离不以胶漆，约束不以纆索。",tone:"常然",guide:"这是《骈拇》全篇最重要的正面命题——天下有常然。常然——自然而然的常态，本来如此的状态。六个「不以」，构成了常然最完整的定义：曲者不以钩（天生弯曲的，不需要钩来弯它）、直者不以绳（天生笔直的，不需要绳来量它）、圆者不以规、方者不以矩、附离不以胶漆、约束不以纆索。六个「不以」的共同指向：万物各有其自然状态——那个自然状态，不需要任何外在工具来实现，它本来就是那样的。礼乐仁义，就是那套多余的工具——天下本来就有常然，不需要礼乐仁义来「端正」它、「固定」它。"},{text:"则仁义又奚连连如胶漆纆索而游乎道德之间为哉！使天下惑也！",tone:"结论",guide:"庄子的结论，是全篇最有力的一句反问：那么，仁义为什么要像胶漆纆索一样，纠缠不休地在道德之间游走干涉？使天下惑也！——这只是在使天下迷惑！「胶漆纆索」——这个比喻，是对仁义最深的解构：胶漆，是用来粘合本来不在一起的东西的；纆索，是用来捆绑本来不受束缚的东西的——仁义，就是这样的胶漆纆索——把本来自然流动的道德，强行粘合、捆绑成一个固定的形状——结果，不是道德更好了，而是天下迷惑了。"}]}),n[21]||(n[21]=i("h2",{id:"六、虞氏招仁义·以仁义易其性",tabindex:"-1"},[e("六、虞氏招仁义·以仁义易其性 "),i("a",{class:"header-anchor",href:"#六、虞氏招仁义·以仁义易其性","aria-label":'Permalink to "六、虞氏招仁义·以仁义易其性"'},"​")],-1)),n[22]||(n[22]=i("h3",{id:"原文-5",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-5","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:z,glossary:c,"default-mode":"classic","aria-label":"骈拇·虞氏招仁义 原文"}),n[23]||(n[23]=i("h3",{id:"字词释义-5",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义-5","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(s,{items:[{term:"小惑易方",pinyin:["xiǎo","huò","yì","fāng"],meaning:"小的迷惑，改变方向（走错路）。"},{term:"大惑易性",pinyin:["dà","huò","yì","xìng"],meaning:"大的迷惑，改变本性（根本性的迷失）。"},{term:"虞氏",pinyin:["yú","shì"],meaning:"即舜，有虞氏。"},{term:"招仁义",pinyin:["zhāo","rén","yì"],meaning:"招：倡导、招引。倡导仁义。"},{term:"挠天下",pinyin:["náo","tiān","xià"],meaning:"挠：扰乱、搅动。扰乱天下。"}]}),n[24]||(n[24]=i("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"小惑易方，大惑易性",subtitle:"仁义对天下的影响，不是小惑，而是大惑——让人失去本性。",lines:[{text:"夫小惑易方，大惑易性。",tone:"定义",guide:"这是《骈拇》中最简洁、最深刻的一句话：小的迷惑——走错了方向，迷了路——还可以找回来，还可以纠正；大的迷惑——改变了本性——这是根本性的迷失，本性一旦被改变，就再也找不回原来的自己。这两句，是对「仁义易性」的定性：仁义对天下的影响，不是小惑，而是大惑——不是让人走错路，而是让人失去本性。"},{text:"自虞氏招仁义以挠天下也，天下莫不奔命于仁义。是非以仁义易其性与？",tone:"历史起点",guide:"庄子把历史的起点，指向虞氏（舜）——这与《应帝王》第一段「有虞氏其犹藏仁以要人」完全呼应——舜，是儒家最推崇的圣王之一；但在庄子看来，正是舜倡导仁义、扰乱天下，开启了「以仁义易性」的历史——天下莫不奔命于仁义——从此，天下人无不拼命奔走于仁义之道——争着做仁人，争着符合仁义的标准——这难道不是用仁义改变了人的本性吗？「奔命」——这个词极为传神：不是自然而然地走向仁义，而是拼命奔走——拼命，正是因为仁义不是本性——本性的事，不需要拼命。"}]}),n[25]||(n[25]=i("h2",{id:"七、以身为殉·小人士大夫圣人·伤性一也",tabindex:"-1"},[e("七、以身为殉·小人士大夫圣人·伤性一也 "),i("a",{class:"header-anchor",href:"#七、以身为殉·小人士大夫圣人·伤性一也","aria-label":'Permalink to "七、以身为殉·小人士大夫圣人·伤性一也"'},"​")],-1)),n[26]||(n[26]=i("h3",{id:"原文-6",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-6","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:f,glossary:q,"default-mode":"classic","aria-label":"骈拇·以身为殉 原文"}),n[27]||(n[27]=i("h3",{id:"字词释义-6",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义-6","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(s,{items:[{term:"以物易其性",pinyin:["yì"],meaning:"易：改变、替换。用外物替换、改变本性。"},{term:"以身殉利",pinyin:["xùn"],meaning:"殉：为某物牺牲生命或本性。为利益牺牲自身。"},{term:"以身殉名",pinyin:["yǐ","shēn","xùn","míng"],meaning:"为名声牺牲自身。"},{term:"以身殉家",pinyin:["yǐ","shēn","xùn","jiā"],meaning:"为家族牺牲自身。"},{term:"以身殉天下",pinyin:["yǐ","shēn","xùn","tiān","xià"],meaning:"为天下牺牲自身。"},{term:"此数子者",pinyin:["cǐ","shù","zǐ","zhě"],meaning:"这几类人。"}]}),n[28]||(n[28]=i("h3",{id:"核心句引读-6",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"小人殉利，圣人殉天下——伤性一也",subtitle:"无论殉的是什么，只要是「殉」——以本性换取外物——就是对本性的伤害。",lines:[{text:"自三代以下者，天下莫不以物易其性矣！",tone:"推广",guide:"第六段说「以仁义易其性」，第七段把这个命题推广到所有人：自三代以下，天下没有人不是在以外物替换本性——不只是仁义，利、名、家、天下——一切外物，都可以成为替换本性的工具。"},{text:"小人则以身殉利；士则以身殉名；大夫则以身殉家；圣人则以身殉天下。",tone:"四类",guide:"庄子列出四个层次，构成一个完整的社会图谱：小人——以身殉利（为利益牺牲本性）；士——以身殉名（为名声牺牲本性）；大夫——以身殉家（为家族牺牲本性）；圣人——以身殉天下（为天下牺牲本性）。这四个层次，从低到高——小人殉利，被认为是卑鄙的；圣人殉天下，被认为是崇高的——但庄子说：故此数子者，事业不同，名声异号，其于伤性以身为殉，一也。事业不同，名声各异——但在伤害本性、以身殉物这件事上，是一样的。这是《骈拇》最有冲击力的命题：圣人殉天下，与小人殉利——在庄子看来，本质上没有区别。不是说圣人与小人道德上相同——而是说：无论殉的是什么，只要是「殉」——以本性换取外物——就是对本性的伤害，就是「以物易其性」。"}]}),n[29]||(n[29]=i("h2",{id:"八、臧与谷·牧羊俱亡·事业不同亡羊均也",tabindex:"-1"},[e("八、臧与谷·牧羊俱亡·事业不同亡羊均也 "),i("a",{class:"header-anchor",href:"#八、臧与谷·牧羊俱亡·事业不同亡羊均也","aria-label":'Permalink to "八、臧与谷·牧羊俱亡·事业不同亡羊均也"'},"​")],-1)),n[30]||(n[30]=i("h3",{id:"原文-7",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-7","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:k,glossary:j,"default-mode":"classic","aria-label":"骈拇·臧谷亡羊 原文"}),n[31]||(n[31]=i("h3",{id:"字词释义-7",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义-7","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(s,{items:[{term:"臧",pinyin:["zāng"],meaning:"人名，牧羊人之一。"},{term:"谷",pinyin:["gǔ"],meaning:"人名，牧羊人之二。"},{term:"相与牧羊",pinyin:["xiāng","yǔ","mù","yáng"],meaning:"一同牧羊。"},{term:"俱亡其羊",pinyin:["jù","wáng","qí","yáng"],meaning:"都丢失了羊。"},{term:"奚事",pinyin:["xī","shì"],meaning:"奚：什么。在做什么事。"},{term:"挟策读书",pinyin:["xié","cè","dú","shū"],meaning:"挟：夹持；策：竹简（书）。夹着书简在读书。"},{term:"博塞以游",pinyin:["bó","sè","yǐ","yóu"],meaning:"博塞：古代一种博弈游戏。以博塞为游乐。"}]}),n[32]||(n[32]=i("h3",{id:"核心句引读-7",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"臧读书，谷游戏——羊都丢了",subtitle:"无论外物高尚还是低俗，一旦沉迷于外物，本性（羊）就丢了。",lines:[{text:"臧与谷，二人相与牧羊而俱亡其羊。",tone:"寓言",guide:"《骈拇》第八段，是全篇最短的一段，也是最精炼的一则寓言——两个牧羊人，一起牧羊，都丢了羊。"},{text:"问臧奚事，则挟策读书；问谷奚事，则博塞以游。",tone:"两事",guide:"臧——在读书（高尚的事）；谷——在玩游戏（消遣的事）。两件事，一高一低，一雅一俗——读书，是士人的正业，是「有意义」的事；博塞，是玩乐，是「无意义」的事。"},{text:"二人者，事业不同，其于亡羊均也。",tone:"亡羊均",guide:"事业不同，亡羊均也。这五个字，是第七段「事业不同，名声异号，其于伤性以身为殉，一也」的直接延伸——结构完全一致：第七段：事业不同·名声异号→伤性一也；第八段：事业不同→亡羊均也。臧谷寓言，是第七段「四类殉者」的具体化——臧读书，是「殉名」的小版本；谷玩游戏，是「殉利（乐）」的小版本——无论殉的是什么，羊都丢了。羊，在这里是一个极妙的象征——羊，就是本性。臧丢了羊，是因为沉迷于读书（高尚的外物）；谷丢了羊，是因为沉迷于游戏（低俗的外物）——无论外物高尚还是低俗，一旦沉迷于外物，本性（羊）就丢了。这则寓言，把第七段的宏大命题，浓缩成一个日常场景——让「以物易性」这个抽象命题，变得触手可及、无可辩驳。"}]}),n[33]||(n[33]=i("h2",{id:"九、伯夷死名·盗跖死利·残生伤性均也",tabindex:"-1"},[e("九、伯夷死名·盗跖死利·残生伤性均也 "),i("a",{class:"header-anchor",href:"#九、伯夷死名·盗跖死利·残生伤性均也","aria-label":'Permalink to "九、伯夷死名·盗跖死利·残生伤性均也"'},"​")],-1)),n[34]||(n[34]=i("h3",{id:"原文-8",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-8","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:w,glossary:P,"default-mode":"classic","aria-label":"骈拇·伯夷盗跖 原文"}),n[35]||(n[35]=i("h3",{id:"字词释义-8",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义-8","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(s,{items:[{term:"伯夷",pinyin:["bó","yí"],meaning:"商末周初人，因不食周粟，饿死于首阳山，以清高节义著称。"},{term:"盗跖",pinyin:["dào","zhí"],meaning:"传说中的大盗，以贪利凶悍著称。"},{term:"所死不同",pinyin:["suǒ","sǐ","bù","tóng"],meaning:"所为而死的原因不同。"},{term:"残生伤性",pinyin:["cán","shēng","shāng","xìng"],meaning:"残：损害；伤：伤害。损害生命、伤害本性。"},{term:"均也",pinyin:["jūn","yě"],meaning:"是一样的。"}]}),n[36]||(n[36]=i("h3",{id:"核心句引读-8",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"所死不同，其于残生伤性均也",subtitle:"真正的问题，不是「你殉的是高尚的还是低俗的」，而是「你殉了吗？你的本性，还在吗？」",lines:[{text:"伯夷死名于首阳之下，盗跖死利于东陵之上。",tone:"两端",guide:"庄子选择了两个极端对立的人物：伯夷——中国传统道德的最高象征——商末周初，武王伐纣，伯夷认为以臣伐君是不义的，周朝建立后，不食周粟，饿死于首阳山——为名节而死，被后世奉为清高节义的典范；盗跖——中国传统道德的最低象征——传说中的大盗，率众劫掠，贪利凶悍——为财利而死，被后世视为贪婪凶残的代表。两人，一个在道德光谱的最高端，一个在道德光谱的最低端——庄子把他们并列，本身就是一个极大的冲击。"},{text:"二人者，所死不同，其于残生伤性均也。奚必伯夷之是而盗跖之非乎？",tone:"均也",guide:"所死不同，残生伤性均也。伯夷为名而死——残生伤性；盗跖为利而死——残生伤性——在残害生命、伤害本性这件事上，是一样的。「奚必伯夷之是而盗跖之非乎？」——为什么一定要说伯夷是对的、盗跖是错的？这个反问，不是在为盗跖辩护，也不是在否定伯夷的节义——庄子的逻辑是：如果评判的标准是「是否残生伤性」，那伯夷与盗跖，没有高下之分——两人都残生伤性了。庄子不是在做道德相对主义——他是在说：用「残生伤性」这个标准来看，世俗的高下之分，根本不成立。真正的问题，不是「你殉的是高尚的还是低俗的」，而是「你殉了吗？你的本性，还在吗？」"}]}),n[37]||(n[37]=i("h2",{id:"十、天下尽殉·君子小人其殉一也",tabindex:"-1"},[e("十、天下尽殉·君子小人其殉一也 "),i("a",{class:"header-anchor",href:"#十、天下尽殉·君子小人其殉一也","aria-label":'Permalink to "十、天下尽殉·君子小人其殉一也"'},"​")],-1)),n[38]||(n[38]=i("h3",{id:"原文-9",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-9","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:T,glossary:v,"default-mode":"classic","aria-label":"骈拇·天下尽殉 原文"}),n[39]||(n[39]=i("h3",{id:"字词释义-9",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义-9","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(s,{items:[{term:"天下尽殉也",pinyin:["tiān","xià","jìn","xùn","yě"],meaning:"天下人都在「殉」（为外物牺牲本性）。"},{term:"其殉一也",pinyin:["qí","xùn","yī","yě"],meaning:"他们的「殉」是一样的。"},{term:"残生损性",pinyin:["cán","shēng","sǔn","xìng"],meaning:"残害生命、损伤本性。"}]}),n[40]||(n[40]=i("h3",{id:"核心句引读-9",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-9","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"天下尽殉——君子小人的区别，只是殉的对象不同",subtitle:"真正的问题，不是你殉的是什么，而是你有没有在「殉」。",lines:[{text:"天下尽殉也。",tone:"四字",guide:"四个字，是《骈拇》全篇最重的一句判断——天下，所有人，都在「殉」。没有例外——不管你殉的是仁义还是货财，不管你被称为君子还是小人——天下尽殉。"},{text:"彼其所殉仁义也，则俗谓之君子；其所殉货财也，则俗谓之小人。其殉一也，则有君子焉，有小人焉。",tone:"解构",guide:"庄子把「君子」与「小人」的区别，彻底解构为殉的对象不同——殉仁义→世俗称君子；殉货财→世俗称小人——但「殉」这件事本身，是一样的——君子与小人的区别，只是世俗给不同的「殉」贴上的不同标签。"},{text:"若其残生损性，则盗跖亦伯夷已，又恶取君子小人于其间哉！",tone:"结论",guide:"如果以残生损性为标准——盗跖也就是伯夷了——哪里还能在其中区分君子小人？这句话，是第九段「奚必伯夷之是而盗跖之非乎」的直接延伸——庄子不是说盗跖与伯夷道德上相同，而是说：在「残生损性」这个维度上，世俗的君子小人之分，根本不成立。这是《骈拇》对儒家道德体系最深的解构：儒家的整个道德体系，建立在君子与小人的区分上——君子殉仁义，小人殉货财——这个区分，是儒家道德教化的基础。庄子说：这个区分，是虚假的——因为两者都在「殉」，都在残生损性——区别只是殉的对象，不是殉这件事本身。真正的问题，不是你殉的是什么，而是你有没有在「殉」。"}]}),n[41]||(n[41]=i("h2",{id:"十一、吾所谓臧·聪·明·自见自得·不适人之适",tabindex:"-1"},[e("十一、吾所谓臧·聪·明·自见自得·不适人之适 "),i("a",{class:"header-anchor",href:"#十一、吾所谓臧·聪·明·自见自得·不适人之适","aria-label":'Permalink to "十一、吾所谓臧·聪·明·自见自得·不适人之适"'},"​")],-1)),n[42]||(n[42]=i("h3",{id:"原文-10",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-10","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:G,glossary:C,"default-mode":"classic","aria-label":"骈拇·自见自得 原文"}),n[43]||(n[43]=i("h3",{id:"字词释义-10",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义-10","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(s,{items:[{term:"俞儿",pinyin:["yú","ér"],meaning:"传说中味觉极为敏锐的人。"},{term:"臧于其德",pinyin:["zāng","yú","qí","dé"],meaning:"善在于保全本真之德而已。"},{term:"自闻",pinyin:["zì","wén"],meaning:"听见自己（内在的声音）而已。真正的聪，是向内的。"},{term:"自见",pinyin:["zì","jiàn"],meaning:"看见自己（内在的本性）而已。真正的明，是向内的。"},{term:"淫僻",pinyin:["yín","pì"],meaning:"过度偏邪，偏离本性。"},{term:"余愧乎道德",pinyin:["yú","kuì","hū","dào","dé"],meaning:"我对道德感到惭愧（自谦，意为敬畏道德）。"},{term:"仁义之操",pinyin:["cāo"],meaning:"操：操守、行为准则。仁义的行为准则。"},{term:"淫僻之行",pinyin:["yín","pì","zhī","xíng"],meaning:"偏离本性的行为。"}]}),n[44]||(n[44]=i("h3",{id:"核心句引读-10",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-10","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"吾所谓聪者，非谓其闻彼也，自闻而已矣；吾所谓明者，非谓其见彼也，自见而已矣",subtitle:"向外的聪明，是骈枝；向内的自闻自见，是本性。",lines:[{text:"属其性乎仁义者，虽通如曾、史，非吾所谓臧也。",tone:"定义",guide:"庄子用四组平行句，重新定义「善·聪·明」——「属其性乎……」——把本性系缚于某物——这是《骈拇》全篇「骈枝」的最终定义：骈枝，就是「属其性」——把本性系缚于某个外物，无论那个外物是仁义、五味、五声、还是五色。四组的结构完全一致：系缚于外物 + 即使精通如……+ 也不是我说的善／聪／明。「虽通如……」——这四个字，是庄子最深的让步：我不否认你的精通，我不否认你的才能——但精通，不等于善；才能，不等于聪明。精通是外在的成就，善·聪·明，是内在的本性状态。"},{text:"吾所谓臧者，非所谓仁义之谓也，臧于其德而已矣；……任其性命之情而已矣。",tone:"臧",guide:"庄子给出自己对「善（臧）」的定义——这两句，是《骈拇》全篇最重要的正面答案：吾所谓臧（善）——不是仁义——臧于其德而已矣（善在于保全本真之德而已）；吾所谓臧（善）——不是仁义——任其性命之情而已矣（善在于顺任本性与天命的真实状态而已）。两句说的是同一件事，两个角度：臧于其德——从「德」的角度：保全本真之德；任其性命之情——从「性命」的角度：顺任本性天命。这与第三段「正正者，不失其性命之情」完全呼应——善，不是做了什么，而是没有失去什么——没有失去本真之德，没有失去性命之情。"},{text:"吾所谓聪者，非谓其闻彼也，自闻而已矣；吾所谓明者，非谓其见彼也，自见而已矣。",tone:"自闻自见",guide:"庄子重新定义「聪」与「明」——这两句，是《骈拇》最精炼的两句话：吾所谓聪——不是听见外物（闻彼）——自闻而已——听见自己（内在的本性）而已；吾所谓明——不是看见外物（见彼）——自见而已——看见自己（内在的本性）而已。「自闻·自见」——这两个词，是《骈拇》全篇的核心答案：师旷的聪，是「闻彼」——听见外在的音律；离朱的明，是「见彼」——看见外在的色彩——这是骈枝，因为它把本性系缚于外物。真正的聪，是自闻——不是听见更多的外在声音，而是听见自己内在的本性之声；真正的明，是自见——不是看见更多的外在事物，而是看见自己内在的本性之光。向外的聪明，是骈枝；向内的自闻自见，是本性。"},{text:"夫适人之适而不自适其适，虽盗跖与伯夷，是同为淫僻也。",tone:"最终结论",guide:"这是《骈拇》全篇最震撼的一句结论：适人之适而不自适其适——无论是盗跖还是伯夷——都是淫僻。「淫僻」——过度偏邪，偏离本性——这个词，在第一段已经出现过：「淫僻于仁义之行」——现在，庄子把它推到极致：伯夷，是儒家道德的最高象征——但如果伯夷的节义，是「适人之适」——是为了符合某种外在的道德标准，而不是「自适其适」——那伯夷，也是淫僻。盗跖，是世俗道德的最低象征——如果盗跖的贪利，是「适人之适」——是为了符合某种外在的欲望标准——那盗跖，也是淫僻。两者，同为淫僻——因为两者都不是「自适其适」。这是《骈拇》对「自见自得」命题最深的展开：真正的善，不在于你做了什么，而在于你做的，是不是出于自己的本性——是不是「自适其适」。"},{text:"余愧乎道德，是以上不敢为仁义之操，而下不敢为淫僻之行也。",tone:"自处",guide:"《骈拇》的最后一句，是庄子罕见的第一人称表态——余愧乎道德（我对道德感到惭愧，敬畏道德的深远）——上不敢为仁义之操（在上，不敢以仁义为操守——不骈枝于仁义）；下不敢为淫僻之行（在下，不敢有淫僻偏邪的行为——不失其本性）。这最后一句，是庄子对自己的定位——也是《骈拇》全篇的最终落点：不是仁义，也不是淫僻——既不向上攀附仁义的高标，也不向下堕入淫僻的偏邪——只是守住那个「自适其适」的本性。这与第三段「正正者，不失其性命之情」首尾呼应——全篇，从「不失性命之情」开始，到「自适其适」结束——是同一件事的两种表达。"}]}),n[45]||(n[45]=l("",38))])}}});export{B as __pageData,K as default};
